        // ══════════════════════════════════════════════════════════════════════
        // FEATURE 1 — SESSION PERSISTENCE (localStorage + Supabase upsert)
        // Saves on every answer to localStorage (instant, free, no quota).
        // Also upserts to Supabase sessions table for cross-device resume.
        // ══════════════════════════════════════════════════════════════════════
        // syncSession — heartbeat function called on every answer + every 60s
        window.cloudSaveSession = async function () {
            const id = localStorage.getItem("inside_oau_id") || "IOU-2026";
            const modeEl = document.getElementById('exam-mode');
            const currentState = {
                student_details: window.studentDetails || {},
                exam_type: (modeEl ? modeEl.value : null) || (window.studentDetails && window.studentDetails.examMode) || "mock",
                time_left: window.timeLeft || 0,
                current_index: window.currentQIndex || 0,
                current_subject: window.currentSubject || "",
                answers_map: window.userAnswers || {},
                exam_snapshot: window.examData || {},
                saved_at: new Date().toISOString()
            };
            // ── Offline backup: localStorage first (always, instant, free) ──────
            try { localStorage.setItem("oau_session_" + id, JSON.stringify(currentState)); } catch (e) { }
            // ── Cloud sync: upsert sessions table (single row per student) ───────
            if (_supabase) {
                _supabase.from('sessions').upsert({
                    student_id: id,
                    current_state: currentState,
                    updated_at: new Date().toISOString()
                }, { onConflict: 'student_id' })
                    .then(function (r) {
                        if (r.error) console.warn("Session sync failed:", r.error.message);
                        else console.debug("Session synced");
                    });
            }
        };

        // _mapState: normalise a current_state object into app state shape
        function _mapState(s) {
            if (!s) return null;
            var tl = s.time_left || 0;
            if (tl <= 0) return null;
            var snap = s.exam_snapshot || s.exam_data || {};
            if (!snap || Object.keys(snap).length === 0) return null;
            return {
                studentDetails: s.student_details || {},
                userAnswers: s.answers_map || s.answers || {},
                examData: snap,
                currentSubject: s.current_subject || Object.keys(snap)[0] || "",
                currentQIndex: s.current_index || 0,
                timeLeft: tl,
                examMode: s.exam_type || s.exam_mode || "mock"
            };
        }

        function _checkLocalResume() {
            try {
                const id = localStorage.getItem("inside_oau_id") || "IOU-2026";
                const raw = localStorage.getItem("oau_session_" + id);
                if (!raw) return null;
                const s = JSON.parse(raw);
                const age = Date.now() - new Date(s.saved_at || s.updated_at || 0).getTime();
                if (age > 3 * 60 * 60 * 1000) { localStorage.removeItem("oau_session_" + id); return null; }
                return _mapState(s);
            } catch (e) { return null; }
        }

        window.cloudCheckResume = async function () {
            // 1. localStorage first — fastest, works offline and on file://
            const local = _checkLocalResume();
            if (local) return local;
            // 2. Supabase fallback — cross-device resume
            if (!_supabase || location.protocol === 'file:') return null;
            const id = localStorage.getItem("inside_oau_id") || "IOU-2026";
            try {
                let _tid;
                const _timeout = new Promise(function (_, rej) {
                    _tid = setTimeout(function () { rej(new Error('timeout')); }, 5000);
                });
                const _query = _supabase
                    .from('sessions')
                    .select('current_state, updated_at')
                    .eq('student_id', id)
                    .single()
                    .then(function (res) { clearTimeout(_tid); return res; });
                const { data, error } = await Promise.race([_query, _timeout]);
                if (error || !data || !data.current_state) return null;
                // Check it's not stale (older than 3 hours)
                var age = Date.now() - new Date(data.updated_at || 0).getTime();
                if (age > 3 * 60 * 60 * 1000) return null;
                return _mapState(data.current_state);
            } catch (e) { console.info("cloudCheckResume bypassed:", e.message); return null; }
        };

        window.cloudClearSession = async function () {
            try {
                const id = localStorage.getItem("inside_oau_id") || "IOU-2026";
                localStorage.removeItem("oau_session_" + id);
                if (_supabase) {
                    _supabase.from('sessions').delete().eq('student_id', id)
                        .then(function (r) { if (r.error) console.warn("Session delete failed:", r.error.message); });
                }
            } catch (e) { }
        };

        // ══════════════════════════════════════════════════════════════════════
        // FEATURE 2 — REAL-TIME LEADERBOARD (Supabase Realtime)
        // ══════════════════════════════════════════════════════════════════════
        function renderLeaderboardUI(rows) {
            const box = document.getElementById('leaderboard-list');
            if (!box) return;
            if (!rows || !rows.length) {
                box.innerHTML = '<p style="text-align:center;color:#888;padding:20px;">No results yet. Be the first! 🏆</p>';
                return;
            }
            const medals = ['🥇', '🥈', '🥉'];
            box.innerHTML = rows.map(function (r, i) {
                return '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid #eee;background:' + (i < 3 ? '#fffde7' : '#fff') + ';">' +
                    '<span style="font-size:1.2rem;width:32px;">' + (medals[i] || '<span style="color:#888">' + (i + 1) + '</span>') + '</span>' +
                    '<span style="flex:1;font-weight:bold;color:#333;margin:0 8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + (r.name || '—') + '</span>' +
                    '<span style="font-weight:900;color:#0056b3;font-size:1.1rem;">' + (r.aggregate || 0) + '<span style="font-size:0.75rem;color:#888;">/400</span></span>' +
                    '</div>';
            }).join('');
        }

        async function _fetchLeaderboard() {
            if (!_supabase) return;
            try {
                // Fetch exams with correct column names (aggregate_score, student_name)
                const examsRes = await _supabase
                    .from('exams')
                    .select('student_id, student_name, raw_score, aggregate_score, created_at')
                    .order('aggregate_score', { ascending: false })
                    .limit(50);

                if (examsRes.error) {
                    console.warn("Leaderboard fetch error:", examsRes.error.message);
                    return;
                }

                const data = examsRes.data || [];

                // student_name is already stored on each row — no extra join needed
                const rows = data.map(function (r, i) {
                    return {
                        rank: i + 1,
                        name: r.student_name || r.student_id || '—',
                        aggregate: r.aggregate_score || 0
                    };
                });

                window._leaderboardData = rows;
                renderLeaderboardUI(rows);
            } catch (e) {
                console.warn("Leaderboard exception:", e.message);
            }
        }

        window.initLeaderboard = function () {
            if (!_supabase) { console.warn("initLeaderboard: Supabase not ready"); return; }
            // Initial fetch
            _fetchLeaderboard();
            // Real-time updates via Supabase channel
            _supabase.channel('results_channel')
                .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'exams' }, function (payload) {
                    console.log("New exam result received, refreshing leaderboard...");
                    _fetchLeaderboard();
                })
                .subscribe(function (status) {
                    if (status === 'SUBSCRIBED') console.log("Leaderboard realtime channel active");
                });
        };

        // ══════════════════════════════════════════════════════════════════════
        // FEATURE 3 — LIVE ONLINE USER COUNTER (Supabase Presence via channel)
        // ══════════════════════════════════════════════════════════════════════
        window.registerPresence = function () {
            if (!_supabase) {
                var el = document.getElementById('live-counter');
                if (el) el.innerHTML = '🔵 Exam in progress';
                return;
            }
            try {
                const myID = localStorage.getItem("inside_oau_id") || ("anon-" + Date.now());
                const presenceChannel = _supabase.channel('exam_presence', {
                    config: { presence: { key: myID } }
                });
                presenceChannel
                    .on('presence', { event: 'sync' }, function () {
                        const state = presenceChannel.presenceState();
                        const n = Object.keys(state).length;
                        var el = document.getElementById('live-counter');
                        if (el) el.innerHTML = '🟢 <strong>' + n + '</strong> student' + (n !== 1 ? 's' : '') + ' writing now';
                    })
                    .on('presence', { event: 'leave' }, function () {
                        const state = presenceChannel.presenceState();
                        const n = Object.keys(state).length;
                        var el = document.getElementById('live-counter');
                        if (el) el.innerHTML = '🟢 <strong>' + n + '</strong> student' + (n !== 1 ? 's' : '') + ' writing now';
                    })
                    .subscribe(async function (status) {
                        if (status === 'SUBSCRIBED') {
                            await presenceChannel.track({ online_at: new Date().toISOString() });
                        }
                    });
                window._presenceChannel = presenceChannel;
                window.addEventListener('beforeunload', function () {
                    if (window._presenceChannel) window._presenceChannel.untrack();
                });
            } catch (e) {
                console.warn("registerPresence failed:", e.message);
                var el = document.getElementById('live-counter');
                if (el) el.innerHTML = '🔵 Exam in progress';
            }
        };

        // ══════════════════════════════════════════════════════════════════════
        // FEATURE 4 — RESULT PUSH + ANTI-CHEAT (Supabase exams table INSERT)
        // Uses INSERT (not upsert) so every attempt creates a new history row.
        // ══════════════════════════════════════════════════════════════════════
        window.cloudPushResult = async function (payload) {
            if (!_supabase) { console.error("cloudPushResult: Supabase not ready"); return; }
            if (!payload || !payload.studentID) { console.error("cloudPushResult: missing studentID"); return; }
            try {
                console.log("Saving result for:", payload.studentID);

                // 1. Upsert profile (name + ID)
                await _supabase.from('profiles').upsert({
                    student_id: payload.studentID,
                    full_name: payload.name || "Unknown"
                }, { onConflict: 'student_id' });

                // 2. INSERT exam record — new row every attempt (full history, never overwritten)
                // raw_data stores subject_scores, user_answers, and exam_snapshot so
                // corrections remain accurate even if the question bank changes later.
                const { data: inserted, error } = await _supabase.from('exams').insert({
                    student_id: payload.studentID,
                    student_name: payload.name || "Unknown",
                    exam_mode: payload.mode || "mock",
                    aggregate_score: payload.jambAggregate || 0,
                    raw_score: payload.totalScore || 0,
                    total_questions: payload.totalQuestions || 0,
                    seal: payload.seal || "",
                    raw_data: {
                        subject_scores: payload.subjectBreakdown || {},
                        user_answers: payload.userAnswers || {},
                        exam_snapshot: payload.examSnapshot || {}
                    }
                }).select('id').single();

                if (error) throw error;
                // Store the inserted row ID so history can refresh immediately
                window._lastInsertedExamId = inserted ? inserted.id : null;
                console.log("%cResult saved to Supabase! ID:", "color:green;font-weight:bold", window._lastInsertedExamId);

                // 3. Refresh history panel if it's visible
                if (typeof loadExamHistory === 'function') loadExamHistory();

            } catch (e) { console.error("Result push FAILED:", e.message); }
        };

        window.cloudCheckRetake = async function (studentID) {
            // Only blocks if a MOCK exam was submitted TODAY (not all-time)
            if (location.protocol === 'file:') { console.info("cloudCheckRetake: skipped (file://)"); return null; }
            if (!_supabase) return null;
            try {
                // Build today's date window (midnight to midnight local time → UTC)
                var now = new Date();
                var start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0).toISOString();
                var end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59).toISOString();

                let _tid2;
                const _timeout2 = new Promise(function (_, rej) {
                    _tid2 = setTimeout(function () { rej(new Error('timeout')); }, 5000);
                });
                const _query2 = _supabase
                    .from('exams')
                    .select('aggregate_score, raw_score, created_at')
                    .eq('student_id', studentID)
                    .eq('exam_mode', 'mock')
                    .gte('created_at', start)
                    .lte('created_at', end)
                    .limit(1)
                    .single()
                    .then(function (res) { clearTimeout(_tid2); return res; });

                const result = await Promise.race([_query2, _timeout2]);
                // No row found is expected — .single() returns error with code PGRST116
                if (!result || !result.data || (result.error && result.error.code === 'PGRST116')) return null;
                if (result.error) return null;
                return {
                    jambAggregate: result.data.aggregate_score || 0,
                    totalScore: result.data.raw_score || 0,
                    timestamp: { seconds: new Date(result.data.created_at).getTime() / 1000 }
                };
            } catch (e) { console.info("cloudCheckRetake bypassed:", e.message); return null; }
        };

        // Signal ready
        window._firebaseReady = true; // kept for compatibility with existing DOMContentLoaded checks
        document.dispatchEvent(new Event('firebaseReady'));

