        // ── PERFORMANCE ANALYTICS CHART ─────────────────────────────────────
        function buildChartHTML(subjectScores) {
            // subjectScores: { english: {score,total,scaled}, maths: {...}, ... }
            const labels = Object.keys(subjectScores).map(s => s.charAt(0).toUpperCase() + s.slice(1));
            const scores = Object.values(subjectScores).map(s => s.scaled);
            const colors = scores.map(s =>
                s >= 70 ? '#28a745' :
                    s >= 50 ? '#ffaa00' : '#dc3545'
            );
            // Unique canvas ID to avoid Chart.js re-render conflicts
            const canvasId = 'perf-chart-' + Date.now();
            // Store data on window so the onload handler can access it
            window._pendingChartData = { canvasId, labels, scores, colors };
            return `
            <div style="background:#fff;border:1px solid #e0e0e0;border-radius:12px;padding:20px;margin:20px 0;text-align:left;">
                <h3 style="color:#0056b3;margin-bottom:4px;font-size:1rem;">📊 Performance Analytics</h3>
                <p style="color:#888;font-size:0.8rem;margin-bottom:14px;">Score per subject (scaled to 100)</p>
                <div style="position:relative;height:220px;">
                    <canvas id="${canvasId}"></canvas>
                </div>
                <div style="display:flex;gap:16px;justify-content:center;margin-top:10px;font-size:0.78rem;flex-wrap:wrap;">
                    <span><span style="display:inline-block;width:12px;height:12px;background:#28a745;border-radius:2px;margin-right:4px;"></span>Strong (70+)</span>
                    <span><span style="display:inline-block;width:12px;height:12px;background:#ffaa00;border-radius:2px;margin-right:4px;"></span>Average (50–69)</span>
                    <span><span style="display:inline-block;width:12px;height:12px;background:#dc3545;border-radius:2px;margin-right:4px;"></span>Needs Work (&lt;50)</span>
                </div>
            </div>`;
        }

        function renderPendingChart() {
            if (!window._pendingChartData) return;
            const { canvasId, labels, scores, colors } = window._pendingChartData;
            const canvas = document.getElementById(canvasId);
            if (!canvas) return;
            window._pendingChartData = null;
            new Chart(canvas, {
                type: 'bar',
                data: {
                    labels,
                    datasets: [{
                        label: 'Score (/100)',
                        data: scores,
                        backgroundColor: colors,
                        borderRadius: 6,
                        borderSkipped: false,
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { display: false },
                        tooltip: {
                            callbacks: {
                                label: ctx => ` ${ctx.parsed.y}/100`
                            }
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            max: 100,
                            ticks: {
                                callback: v => v + '%',
                                stepSize: 20
                            },
                            grid: { color: '#f0f0f0' }
                        },
                        x: { grid: { display: false } }
                    }
                }
            });
        }
        // ─────────────────────────────────────────────────────────────────────

        // Renamed from submit() to avoid HTML conflicts, and added Subject Breakdown
        function finishExam() {
            clearInterval(timerInterval); // Stop the clock

            let totalScore = 0;
            let totalQuestions = 0;
            let totalAggregate = 0;
            let subjectBreakdownHTML = '<div style="margin: 20px 0; border: 1px solid #ddd; border-radius: 8px; padding: 15px; background: #fafafa;">';

            // Calculate score per subject
            // Calculate score per subject
            for (let sub in examData) {
                let subScore = 0;
                let subTotal = examData[sub].length;

                examData[sub].forEach((q, i) => {
                    if (userAnswers[sub] && userAnswers[sub][i] === q.answer) {
                        subScore++;
                    }
                });

                totalScore += subScore;
                totalQuestions += subTotal;

                // Calculate JAMB Aggregate (Scale each subject to 100)
                let scaledScore = Math.round((subScore / subTotal) * 100) || 0;
                totalAggregate += scaledScore;

                // Build the breakdown UI for this subject
                subjectBreakdownHTML += `
            <div style="display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee;">
                <span style="font-weight: bold; text-transform: capitalize; color: #333;">${sub}</span>
                <span><strong style="color: #0056b3;">${subScore} / ${subTotal}</strong></span>
            </div>
        `;
            }
            subjectBreakdownHTML += '</div>';

            // Build subject scores object for chart
            const subjectScores = {};
            for (let sub in examData) {
                let sc = 0;
                examData[sub].forEach((q, i) => { if (userAnswers[sub] && userAnswers[sub][i] === q.answer) sc++; });
                subjectScores[sub] = {
                    score: sc,
                    total: examData[sub].length,
                    scaled: Math.round((sc / examData[sub].length) * 100) || 0
                };
            }
            const chartHTML = buildChartHTML(subjectScores);

            let mode = document.getElementById('exam-mode').value;
            let studentID = localStorage.getItem("inside_oau_id") || "IOU-2026";
            let correctionsHTML = generateCorrectionsHTML();

            // ── Push result to Supabase (with full exam snapshot for history) ──
            if (window.cloudPushResult) {
                // Build subject breakdown
                const subBreakdown = {};
                for (let s in examData) {
                    let sc = 0;
                    examData[s].forEach((q, i) => { if (userAnswers[s] && userAnswers[s][i] === q.answer) sc++; });
                    subBreakdown[s] = { score: sc, total: examData[s].length };
                }
                window.cloudPushResult({
                    studentID,
                    name: studentDetails.name || "Unknown",
                    totalScore,
                    totalQuestions,
                    jambAggregate: totalAggregate,
                    seal: btoa(totalScore + "|" + (studentDetails.name || "").toUpperCase() + "|INSIDE_OAU_SECURE_2026"),
                    mode,
                    subjectBreakdown: subBreakdown,
                    userAnswers: userAnswers,   // exact answers for history corrections
                    examSnapshot: examData       // full question set snapshot
                });
            }
            // ── Do NOT clear session here — only unlockAndSubmit() clears it ──
            // This prevents students from resuming a finished exam, while still
            // allowing them to see their result if they refresh before submitting.
            clearInterval(window._timerInterval); // stop any residual ticks

            // 1. Hide the quiz, show the results div
            document.getElementById('quiz-interface').style.display = 'none';
            const resultBox = document.getElementById('result-interface');
            resultBox.style.display = 'block';

            // 2. SEAL LOGIC (For your Decoder)
            let cleanName = studentDetails.name.toUpperCase();
            let secretSalt = "INSIDE_OAU_SECURE_2026";
            let verificationHash = btoa(totalScore + "|" + cleanName + "|" + secretSalt);

            window._shareCardData = { name: cleanName, studentID, totalScore, totalQuestions, totalAggregate, subjectScores, mode };

            let rawMsg = `*🏆 Inside OAU!𓃵 Mock Result*\n*Name:* ${cleanName}\n*ID:* ${studentID}\n*Raw Score:* ${totalScore}/${totalQuestions}\n*JAMB Aggregate:* ${totalAggregate}/400\n*Seal:* ${verificationHash}`;
            window.currentMockMsg = encodeURIComponent(rawMsg);

            // 3. RENDER THE UI — Multi-page result flow
            // Page nav helper
            window._resultPages = ['page-score', 'page-sharecard', 'page-corrections'];
            window._hasSubmitted = (mode === 'practice'); // practice: always unlocked; mock: locked until WhatsApp submit
            window.showResultPage = function (id) {
                // Block corrections tab until WhatsApp has been submitted (mock mode)
                if (id === 'page-corrections' && !window._hasSubmitted) {
                    alert('🔒 Please submit your result to the Admin via WhatsApp to unlock the Corrections & Review.');
                    return;
                }
                window._resultPages.forEach(function (p) {
                    var el = document.getElementById(p);
                    if (el) el.style.display = 'none';
                });
                var target = document.getElementById(id);
                if (target) { target.style.display = 'block'; window.scrollTo(0, 0); }
                // Update tab highlights
                document.querySelectorAll('.result-tab-btn').forEach(function (b) {
                    b.style.background = b.dataset.page === id ? '#0056b3' : '#e0e0e0';
                    b.style.color = b.dataset.page === id ? '#fff' : '#333';
                });
                if (id === 'page-score') setTimeout(renderPendingChart, 100);
                if (id === 'page-sharecard') { generateShareCard(); }
            };

            // Shared tab bar
            var tabBar = '<div style="display:flex;gap:0;margin-bottom:0;border-radius:10px 10px 0 0;overflow:hidden;border:2px solid #0056b3;border-bottom:none;">' +
                '<button class="result-tab-btn" data-page="page-score" onclick="showResultPage(&apos;page-score&apos;)" style="flex:1;padding:12px 6px;background:#0056b3;color:#fff;border:none;cursor:pointer;font-weight:bold;font-size:0.9rem;">📊 Score</button>' +
                '<button class="result-tab-btn" data-page="page-sharecard" onclick="showResultPage(&apos;page-sharecard&apos;)" style="flex:1;padding:12px 6px;background:#e0e0e0;color:#333;border:none;border-left:2px solid #0056b3;cursor:pointer;font-weight:bold;font-size:0.9rem;">📲 Share</button>' +
                '<button id="review-tab-btn" class="result-tab-btn" data-page="page-corrections" onclick="showResultPage(&apos;page-corrections&apos;)" style="flex:1;padding:12px 6px;background:#e0e0e0;color:#333;border:none;border-left:2px solid #0056b3;cursor:pointer;font-weight:bold;font-size:0.9rem;">🔒 Review</button>' +
                '</div>';

            var pageWrap = 'style="border:2px solid #0056b3;border-top:none;border-radius:0 0 15px 15px;background:#fff;padding:24px 20px;"';

            // ── Build progress trend string for result page ─────────────────
            var trendNotice = '';
            if (window._examHistoryCache) {
                var pastRows = Object.values(window._examHistoryCache).filter(function (r) { return r.exam_mode === mode; });
                pastRows.sort(function (a, b) { return new Date(b.created_at) - new Date(a.created_at); });
                if (pastRows.length >= 1) {
                    var prev = pastRows[0].aggregate_score || 0;
                    var diff = totalAggregate - prev;
                    if (diff > 0) trendNotice = '<div style="background:#d4edda;border:1px solid #c3e6cb;border-radius:8px;padding:8px 14px;margin:10px 0;font-size:0.9rem;">📈 <strong>+' + diff + ' pts</strong> improvement since your last ' + mode + '!</div>';
                    else if (diff < 0) trendNotice = '<div style="background:#f8d7da;border:1px solid #f5c6cb;border-radius:8px;padding:8px 14px;margin:10px 0;font-size:0.9rem;">📉 <strong>' + diff + ' pts</strong> compared to your last ' + mode + '. Keep pushing!</div>';
                }
            }

            if (mode === 'practice') {
                resultBox.innerHTML = tabBar +
                    // PAGE 1 — Score
                    '<div id="page-score" ' + pageWrap + '>' +
                    '<div style="text-align:center;">' +
                    '<h2 style="color:#0056b3;">Practice Finished! 🎯</h2>' +
                    trendNotice +
                    '<div style="font-size:3rem;font-weight:bold;color:#28a745;">' + totalScore + ' / ' + totalQuestions + '</div>' +
                    '</div>' +
                    chartHTML +
                    subjectBreakdownHTML +
                    '<button onclick="showResultPage(&apos;page-corrections&apos;)" style="margin-top:18px;width:100%;padding:14px;background:#ffaa00;color:#000;border:none;border-radius:8px;cursor:pointer;font-weight:bold;font-size:1rem;">📝 View Corrections &rarr;</button>' +
                    '<button onclick="showResultPage(&apos;page-sharecard&apos;)" style="margin-top:10px;width:100%;padding:14px;background:#25D366;color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:bold;font-size:1rem;">📲 Share Result on WhatsApp &rarr;</button>' +
                    '</div>' +
                    // PAGE 2 — Share Card
                    '<div id="page-sharecard" style="display:none;border:2px solid #0056b3;border-top:none;border-radius:0 0 15px 15px;background:#fff;padding:24px 20px;">' +
                    '<h3 style="color:#0056b3;text-align:center;margin-bottom:4px;">Your Result Card</h3>' +
                    '<p style="text-align:center;color:#888;font-size:0.85rem;margin-bottom:10px;">Save the image below and share on WhatsApp Status!</p>' +
                    '<div id="share-card-section"></div>' +
                    '</div>' +
                    // PAGE 3 — Corrections
                    '<div id="page-corrections" style="display:none;border:2px solid #0056b3;border-top:none;border-radius:0 0 15px 15px;background:#fff;padding:24px 20px;">' +
                    '<button onclick="showResultPage(&apos;page-score&apos;)" style="margin-bottom:16px;padding:8px 16px;background:#6c757d;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:bold;">&larr; Back to Score</button>' +
                    correctionsHTML +
                    '</div>';
                setTimeout(renderPendingChart, 100);

            } else {
                // Mock Mode
                resultBox.innerHTML = tabBar +
                    // PAGE 1 — Score
                    '<div id="page-score" ' + pageWrap + '>' +
                    '<div style="text-align:center;">' +
                    '<h2 style="color:#0056b3;">Mock Exam Finished! 🏆</h2>' +
                    '<div style="font-size:3rem;font-weight:bold;color:#555;margin:10px 0;">Raw Score: ' + totalScore + ' / ' + totalQuestions + '</div>' +
                    '<p style="font-size:1.8rem;color:#28a745;font-weight:900;">JAMB Aggregate: <strong>' + totalAggregate + ' / 400</strong></p>' +
                    '</div>' +
                    chartHTML +
                    subjectBreakdownHTML +
                    '<div style="background:#fff3cd;border:2px solid #ffeeba;padding:18px;border-radius:12px;margin:18px 0;">' +
                    '<p style="color:#856404;font-weight:900;margin:0 0 8px;font-size:1.1rem;">🔒 CORRECTIONS LOCKED</p>' +
                    '<p style="color:#856404;font-size:0.95rem;margin:0 0 12px;">Submit your result to Admin to unlock corrections.</p>' +
                    '<button onclick="unlockAndSubmit()" style="width:100%;padding:16px;background:#25D366;color:white;border:none;border-radius:50px;cursor:pointer;font-weight:bold;font-size:1.05rem;box-shadow:0 4px 15px rgba(37,211,102,0.4);">📩 Submit Result & Unlock Corrections</button>' +
                    '</div>' +
                    '<button onclick="showResultPage(&apos;page-sharecard&apos;)" style="margin-top:10px;width:100%;padding:14px;background:#25D366;color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:bold;font-size:1rem;">📲 Share Result on WhatsApp &rarr;</button>' +
                    '</div>' +
                    // PAGE 2 — Share Card
                    '<div id="page-sharecard" style="display:none;border:2px solid #0056b3;border-top:none;border-radius:0 0 15px 15px;background:#fff;padding:24px 20px;">' +
                    '<h3 style="color:#0056b3;text-align:center;margin-bottom:4px;">Your Result Card</h3>' +
                    '<p style="text-align:center;color:#888;font-size:0.85rem;margin-bottom:10px;">Save the image below and share on WhatsApp Status!</p>' +
                    '<div id="share-card-section"></div>' +
                    '</div>' +
                    // PAGE 3 — Corrections (unlocked after WhatsApp submit)
                    '<div id="page-corrections" style="display:none;border:2px solid #0056b3;border-top:none;border-radius:0 0 15px 15px;background:#fff;padding:24px 20px;">' +
                    '<button onclick="showResultPage(&apos;page-score&apos;)" style="margin-bottom:16px;padding:8px 16px;background:#6c757d;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:bold;">&larr; Back to Score</button>' +
                    '<div id="mock-corrections">' + correctionsHTML + '</div>' +
                    '</div>';
                setTimeout(renderPendingChart, 100);
            }
        }

        function getOrGenerateID() {
            // 1. Check if they already have an ID saved on their phone
            let studentID = localStorage.getItem("inside_oau_id");

            // 2. If they don't have one, create it!
            if (!studentID) {
                // Generates a random 5-digit number
                let randomNum = Math.floor(10000 + Math.random() * 90000);
                studentID = "IOU-2026-" + randomNum;

                // Save it permanently to their phone's browser
                localStorage.setItem("inside_oau_id", studentID);
            }

            return studentID;
        }
        // This runs automatically when the page loads
        // Script is in <body> so DOM is already ready — run directly
        (function () {
            let idBox = document.getElementById('cand-reg');
            if (idBox) {
                idBox.value = getOrGenerateID();
            }
            // Init leaderboard listener as soon as Firebase is ready (for modal pre-load)
            if (window._firebaseReady) {
                window.initLeaderboard && window.initLeaderboard();
            } else {
                document.addEventListener('firebaseReady', () => {
                    window.initLeaderboard && window.initLeaderboard();
                });
            }
        })();
        // CALCULATOR LOGIC
        function toggleCalc() { let c = document.getElementById('simple-calc-box'); c.style.display = c.style.display === 'block' ? 'none' : 'block'; }

        function showUtmeHome() {
            // Hide exam/result/history views
            var quiz = document.getElementById('quiz-interface');
            var result = document.getElementById('result-interface');
            var resultAlt = document.getElementById('result-interface-alt');
            var history = document.getElementById('history-card');
            if (quiz) quiz.style.display = 'none';
            if (result) result.style.display = 'none';
            if (resultAlt) { resultAlt.style.display = 'none'; resultAlt.innerHTML = ''; }
            if (history) history.style.display = 'none';
            // Show home view, hide mode panel
            var homeView = document.getElementById('utme-home-view');
            if (homeView) homeView.classList.remove('hidden');
            var modePanel = document.getElementById('utme-mode-panel');
            if (modePanel) modePanel.classList.remove('active');
        }

        function openUtmeMockMode() {
            document.getElementById('exam-mode').value = 'mock';
            document.getElementById('utme-mode-title').textContent = '🎯 Mock Exam';
            document.getElementById('utme-mode-badge').textContent = '180 Qs · 2 Hrs';
            document.getElementById('utme-mode-badge').style.background = 'rgba(var(--th-primary-rgb),0.12)';
            var codeGroup = document.getElementById('utme-code-group');
            if (codeGroup) codeGroup.style.display = 'block';
            updatePracticeInputs();
            document.getElementById('utme-home-view').style.display = 'none';
            document.getElementById('utme-mode-panel').style.display = 'block';
            window.scrollTo(0,0);
            var us = document.getElementById('utme-screen'); if (us) us.scrollTop = 0;
        }

        function openUtmePracticeMode() {
            document.getElementById('exam-mode').value = 'practice';
            document.getElementById('utme-mode-title').textContent = '📝 Practice Mode';
            document.getElementById('utme-mode-badge').textContent = 'Custom · Free';
            document.getElementById('utme-mode-badge').style.background = 'rgba(22,163,74,0.12)';
            document.getElementById('utme-mode-badge').style.color = '#16a34a';
            var codeGroup = document.getElementById('utme-code-group');
            if (codeGroup) codeGroup.style.display = 'none';
            updatePracticeInputs();
            document.getElementById('utme-home-view').style.display = 'none';
            document.getElementById('utme-mode-panel').style.display = 'block';
            window.scrollTo(0,0);
            var us = document.getElementById('utme-screen'); if (us) us.scrollTop = 0;
        }

        function closeUtmeModePanel() {
            document.getElementById('utme-mode-panel').style.display = 'none';
            document.getElementById('utme-home-view').style.display = 'block';
            window.scrollTo(0,0);
            var us = document.getElementById('utme-screen'); if (us) us.scrollTop = 0;
        }

        function utmeToggleSubject(chip) {
            if (chip.classList.contains('utme-locked')) return;
            var selected = document.querySelectorAll('.utme-subject-chip.utme-selected:not(.utme-locked)');
            if (!chip.classList.contains('utme-selected') && selected.length >= 3) {
                alert('You can only select up to 3 elective subjects (4 total including Use of English).');
                return;
            }
            chip.classList.toggle('utme-selected');
            updatePracticeInputs();
        }
        function press(v) { document.getElementById('calc-screen').value += v; }
        function solve() { try { let s = document.getElementById('calc-screen'); s.value = eval(s.value); } catch { s.value = "Error"; } }


        function unlockAndSubmit() {
            // 1. Open WhatsApp with the result message
            window.open('https://wa.me/' + ADMIN_WHATSAPP + '?text=' + window.currentMockMsg, '_blank');

            // 2. Unlock the corrections tab
            window._hasSubmitted = true;
            var tabBtn = document.getElementById('review-tab-btn');
            if (tabBtn) tabBtn.innerHTML = '📝 Review';

            // 3. Clear the session — exam is officially done, no resuming allowed
            clearTimeout(window._cloudSaveTimer);
            clearInterval(window._timerInterval);
            if (window.cloudClearSession) window.cloudClearSession();

            // 4. Navigate to corrections page
            if (window.showResultPage) {
                setTimeout(function () { window.showResultPage('page-corrections'); }, 400);
            } else {
                var box = document.getElementById('mock-corrections');
                if (box) { box.style.display = 'block'; box.scrollIntoView({ behavior: 'smooth' }); }
            }
        }

        // ══════════════════════════════════════════════════════════════════
        // EXAM HISTORY — Load & Display past attempts from Supabase
        // ══════════════════════════════════════════════════════════════════
        async function loadExamHistory() {
            var historyCard = document.getElementById('history-card');
            var historyList = document.getElementById('history-list');
            if (!historyCard || !historyList) return;

            var studentID = localStorage.getItem("inside_oau_id");
            if (!studentID || !window._supabase) { historyCard.style.display = 'none'; return; }

            try {
                var res = await window._supabase
                    .from('exams')
                    .select('id, exam_mode, aggregate_score, raw_score, total_questions, raw_data, created_at')
                    .eq('student_id', studentID)
                    .order('created_at', { ascending: false })
                    .limit(20);

                if (res.error || !res.data || res.data.length === 0) {
                    historyCard.style.display = 'none';
                    return;
                }

                historyCard.style.display = 'block';
                var rows = res.data;

                // ── Progress Trend (compare latest two mock scores) ──────────
                var mocks = rows.filter(function (r) { return r.exam_mode === 'mock'; });
                var trendHTML = '';
                if (mocks.length >= 2) {
                    var diff = mocks[0].aggregate_score - mocks[1].aggregate_score;
                    var arrow = diff > 0 ? '📈' : diff < 0 ? '📉' : '➡️';
                    var colour = diff > 0 ? '#28a745' : diff < 0 ? '#dc3545' : '#888';
                    var pct = Math.abs(Math.round((diff / (mocks[1].aggregate_score || 1)) * 100));
                    trendHTML = '<div style="background:#f0f8ff;border:1px solid #b3d9ff;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:0.9rem;">' +
                        arrow + ' <strong style="color:' + colour + ';">Your score ' + (diff > 0 ? 'improved' : diff < 0 ? 'dropped' : 'stayed the same') +
                        (diff !== 0 ? ' by ' + pct + '%' : '') + '</strong> since your last Mock.' +
                        '</div>';
                }

                // ── History List ─────────────────────────────────────────────
                var html = trendHTML;
                rows.forEach(function (row) {
                    var date = new Date(row.created_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short', year: 'numeric' });
                    var modeLabel = row.exam_mode === 'mock' ? '🎯 Mock' : '📝 Practice';
                    var agg = row.aggregate_score || 0;
                    var aggColour = agg >= 300 ? '#28a745' : agg >= 200 ? '#0056b3' : agg >= 100 ? '#ffaa00' : '#dc3545';
                    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #eee;flex-wrap:wrap;gap:8px;">' +
                        '<div>' +
                        '<div style="font-size:0.8rem;color:#888;">' + date + ' &nbsp;|&nbsp; ' + modeLabel + '</div>' +
                        '<div style="font-weight:bold;color:' + aggColour + ';font-size:1.1rem;">' + agg + '/400 &nbsp;<span style="color:#888;font-size:0.8rem;">(' + (row.raw_score || 0) + '/' + (row.total_questions || 0) + ' raw)</span></div>' +
                        '</div>' +
                        '<button onclick="viewHistoryReview(\'' + row.id + '\')" ' +
                        'style="padding:8px 16px;background:#0056b3;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:0.85rem;font-weight:bold;">View Review</button>' +
                        '</div>';
                });

                historyList.innerHTML = html;
                // Cache rows for corrections lookup
                window._examHistoryCache = {};
                rows.forEach(function (r) { window._examHistoryCache[r.id] = r; });

            } catch (e) {
                console.warn("loadExamHistory failed:", e.message);
                historyCard.style.display = 'none';
            }
        }

        function viewHistoryCorrections(examId, date, agg, mode) {
            var modal = document.getElementById('history-modal');
            var body = document.getElementById('history-modal-body');
            var title = document.getElementById('history-modal-title');
            if (!modal || !body) return;

            var row = window._examHistoryCache && window._examHistoryCache[examId];
            if (!row || !row.raw_data) {
                body.innerHTML = '<p style="color:#888;text-align:center;padding:20px;">No correction data available for this attempt.</p>';
                modal.style.display = 'block';
                return;
            }

            var examSnapshot = row.raw_data.exam_snapshot || {};
            var userAnswers = row.raw_data.user_answers || {};
            var subjectScores = row.raw_data.subject_scores || {};

            title.innerHTML = (mode === 'mock' ? '🎯 Mock' : '📝 Practice') + ' — ' + date + ' &nbsp; <span style="color:#28a745;">' + agg + '/400</span>';

            // Subject score summary
            var summaryHTML = '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px;">';
            Object.entries(subjectScores).forEach(function (e) {
                var sub = e[0], data = e[1];
                var sc = data.score || 0, tot = data.total || 0;
                var pct = Math.round((sc / tot) * 100) || 0;
                var bg = pct >= 70 ? '#d4edda' : pct >= 50 ? '#fff3cd' : '#f8d7da';
                summaryHTML += '<span style="background:' + bg + ';padding:4px 10px;border-radius:20px;font-size:0.82rem;font-weight:bold;text-transform:capitalize;">' +
                    sub + ': ' + sc + '/' + tot + '</span>';
            });
            summaryHTML += '</div>';

            body.innerHTML = summaryHTML + generateCorrectionsFromHistory(examSnapshot, userAnswers);
            modal.style.display = 'block';
            window.scrollTo(0, 0);
        }

        // viewHistoryReview — called by the View Review button
        // Looks up the exam in the cache and renders corrections in the modal
        function viewHistoryReview(examId) {
            var modal = document.getElementById('history-modal');
            var body = document.getElementById('history-modal-body');
            var title = document.getElementById('history-modal-title');
            if (!modal || !body) return;

            // Fetch from Supabase if not in cache (e.g. after page refresh)
            var row = window._examHistoryCache && window._examHistoryCache[examId];
            if (!row) {
                if (!window._supabase) {
                    body.innerHTML = '<p style="color:#888;text-align:center;padding:20px;">Not connected. Please refresh and try again.</p>';
                    modal.style.display = 'block';
                    return;
                }
                modal.style.display = 'block';
                body.innerHTML = '<p style="text-align:center;padding:30px;color:#888;">Loading...</p>';
                window._supabase
                    .from('exams')
                    .select('id, exam_mode, aggregate_score, raw_score, total_questions, raw_data, created_at')
                    .eq('id', examId)
                    .single()
                    .then(function (res) {
                        if (res.error || !res.data) {
                            body.innerHTML = '<p style="color:#dc3545;text-align:center;padding:20px;">Could not load corrections: ' + (res.error ? res.error.message : 'No data') + '</p>';
                            return;
                        }
                        if (!window._examHistoryCache) window._examHistoryCache = {};
                        window._examHistoryCache[examId] = res.data;
                        _renderHistoryModal(res.data);
                    });
                return;
            }
            _renderHistoryModal(row);
        }

        // Internal helper — renders the modal from a cached exam row
        function _renderHistoryModal(row) {
            var modal = document.getElementById('history-modal');
            var body = document.getElementById('history-modal-body');
            var title = document.getElementById('history-modal-title');

            var date = new Date(row.created_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short', year: 'numeric' });
            var agg = row.aggregate_score || 0;
            var mode = row.exam_mode || 'mock';

            title.innerHTML = (mode === 'mock' ? '🎯 Mock' : '📝 Practice') + ' — ' + date +
                ' &nbsp; <span style="color:#28a745;">' + agg + '/400</span>';

            if (!row.raw_data) {
                body.innerHTML = '<p style="color:#888;text-align:center;padding:20px;">No correction data for this attempt. This exam was taken before corrections were enabled.</p>';
                modal.style.display = 'block';
                return;
            }

            var examSnapshot = row.raw_data.exam_snapshot || {};
            var userAnswersHist = row.raw_data.user_answers || {};
            var subjectScores = row.raw_data.subject_scores || {};

            // Subject score summary badges
            var summaryHTML = '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px;">';
            Object.entries(subjectScores).forEach(function (entry) {
                var sub = entry[0], data = entry[1];
                var sc = data.score || 0, tot = data.total || 0;
                var pct = tot > 0 ? Math.round((sc / tot) * 100) : 0;
                var bg = pct >= 70 ? '#d4edda' : pct >= 50 ? '#fff3cd' : '#f8d7da';
                summaryHTML += '<span style="background:' + bg + ';padding:4px 10px;border-radius:20px;font-size:0.82rem;font-weight:bold;text-transform:capitalize;">' +
                    sub + ': ' + sc + '/' + tot + ' (' + pct + '%)</span>';
            });
            summaryHTML += '</div>';

            if (Object.keys(examSnapshot).length === 0) {
                body.innerHTML = summaryHTML + '<p style="color:#888;text-align:center;padding:20px;">Question snapshot not available for this attempt.</p>';
            } else {
                body.innerHTML = summaryHTML + generateCorrectionsFromHistory(examSnapshot, userAnswersHist);
            }
            modal.style.display = 'block';
            window.scrollTo(0, 0);
        }

        // Load history whenever the student ID box has a value (on page load)
        (function () {
            function tryLoadHistory() {
                var id = localStorage.getItem("inside_oau_id");
                if (id && window._supabase) {
                    loadExamHistory();
                } else if (!window._supabase) {
                    document.addEventListener('firebaseReady', function () { loadExamHistory(); });
                }
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', tryLoadHistory);
            } else {
                tryLoadHistory();
            }
        })();

        // ══════════════════════════════════════════════════════════════════
        // DUAL-PORTAL AUTH SYSTEM — New email/password flow
        // Uses _postSupabase (new project) for auth; UTME engine untouched.
        // ══════════════════════════════════════════════════════════════════

        // ── Helpers ──────────────────────────────────────────────────────
        function _authSetError(elId, msg) {
            var el = document.getElementById(elId);
            if (!el) return;
            el.textContent = msg;
            el.style.display = msg ? 'block' : 'none';
        }
        function _authSetSuccess(elId, msg) {
            var el = document.getElementById(elId);
            if (!el) return;
            el.textContent = msg;
            el.style.display = msg ? 'block' : 'none';
        }
        function _authSetBtnLoading(btnId, loading, defaultText) {
            var btn = document.getElementById(btnId);
            if (!btn) return;
            btn.disabled = loading;
            btn.textContent = loading ? 'Please wait…' : defaultText;
        }

        // ── Tab switcher ──────────────────────────────────────────────────
        function switchAuthTab(tab) {
            document.getElementById('tab-signin').classList.toggle('active', tab === 'signin');
            document.getElementById('tab-signup').classList.toggle('active', tab === 'signup');
            document.getElementById('auth-form-signin').classList.toggle('active', tab === 'signin');
            document.getElementById('auth-form-signup').classList.toggle('active', tab === 'signup');
        }

        // ── Sign In ───────────────────────────────────────────────────────
        async function doSignIn() {
            if (!_postSupabase) {
                _authSetError('signin-error', 'Auth service not configured yet. Add your Post-UTME Supabase credentials.');
                return;
            }
            var email = (document.getElementById('signin-email')?.value || '').trim();
            var password = (document.getElementById('signin-password')?.value || '').trim();

            _authSetError('signin-error', '');
            _authSetSuccess('signin-success', '');

            if (!email || !password) {
                _authSetError('signin-error', 'Please enter both email and password.');
                return;
            }

            _authSetBtnLoading('signin-btn', true, 'Sign In');
            try {
                var { data, error } = await _postSupabase.auth.signInWithPassword({ email, password });
                if (error) throw error;
                _authSetSuccess('signin-success', 'Signed in! Loading your portal…');
                await _onAuthSuccess(data.user);
            } catch (e) {
                var msg = e.message || 'Sign in failed.';
                if (msg.toLowerCase().includes('invalid login')) msg = 'Incorrect email or password.';
                _authSetError('signin-error', msg);
            } finally {
                _authSetBtnLoading('signin-btn', false, 'Sign In');
            }
        }

        // ── Sign Up ───────────────────────────────────────────────────────
        async function doSignUp() {
            if (!_postSupabase) {
                _authSetError('signup-error', 'Auth service not configured yet. Add your Post-UTME Supabase credentials.');
                return;
            }
            var name = (document.getElementById('signup-name')?.value || '').trim();
            var email = (document.getElementById('signup-email')?.value || '').trim();
            var password = (document.getElementById('signup-password')?.value || '').trim();
            var confirm = (document.getElementById('signup-confirm')?.value || '').trim();

            _authSetError('signup-error', '');
            _authSetSuccess('signup-success', '');

            if (!name || !email || !password) {
                _authSetError('signup-error', 'Please fill in all fields.');
                return;
            }
            if (password.length < 6) {
                _authSetError('signup-error', 'Password must be at least 6 characters.');
                return;
            }
            if (password !== confirm) {
                _authSetError('signup-error', 'Passwords do not match.');
                return;
            }

            _authSetBtnLoading('signup-btn', true, 'Create Account');
            try {
                var { data, error } = await _postSupabase.auth.signUp({
                    email,
                    password,
                    options: { data: { full_name: name } }
                });
                if (error) throw error;

                if (data.user && data.user.identities && data.user.identities.length === 0) {
                    _authSetError('signup-error', 'An account with this email already exists. Please sign in.');
                    return;
                }

                _authSetSuccess('signup-success', 'Account created! Signing you in…');
                // Auto sign-in after sign-up
                var { data: siData, error: siErr } = await _postSupabase.auth.signInWithPassword({ email, password });
                if (siErr) throw siErr;
                await _onAuthSuccess(siData.user);
            } catch (e) {
                var errMsg = e.message || 'Sign-up failed.';
                if (errMsg.toLowerCase().includes('already registered')) errMsg = 'Email already in use. Please sign in.';
                _authSetError('signup-error', errMsg);
            } finally {
                _authSetBtnLoading('signup-btn', false, 'Create Account');
            }
        }

        // ── Password Reset ────────────────────────────────────────────────
        async function doPasswordReset() {
            if (!_postSupabase) return;
            var email = (document.getElementById('signin-email')?.value || '').trim();
            if (!email) {
                _authSetError('signin-error', 'Enter your email above, then click Reset.');
                return;
            }
            try {
                await _postSupabase.auth.resetPasswordForEmail(email, {
                    redirectTo: location.origin + location.pathname
                });
                _authSetSuccess('signin-success', 'Password reset email sent! Check your inbox.');
            } catch (e) {
                _authSetError('signin-error', 'Reset failed: ' + (e.message || 'Unknown error'));
            }
        }


        // ── Refresh-reminder banner (shown on every login) ────────────────
        function _showRefreshBanner() {
            // Only show while the portal selector is still on screen
            var _ps = document.getElementById('portal-selector');
            if (!_ps || !_ps.classList.contains('visible')) return;
            var old = document.getElementById('refresh-reminder-banner');
            if (old) old.remove();
            var b = document.createElement('div');
            b.id = 'refresh-reminder-banner';

            function _dismissBanner() {
                var el = document.getElementById('refresh-reminder-banner');
                if (el) el.remove();
                document.body.classList.remove('has-refresh-banner');
            }
            window._dismissRefreshBanner = _dismissBanner;

            b.innerHTML =
                '<span class="rrb-text">🔄 <strong>Always refresh the app</strong> when you log in to get the latest updates &amp; questions!</span>' +
                '<div class="rrb-actions">' +
                  '<button id="rrb-refresh-btn" onclick="window.location.reload()">Refresh Now</button>' +
                  '<button id="rrb-close-btn" title="Dismiss">✕</button>' +
                '</div>';
            document.body.appendChild(b);
            document.body.classList.add('has-refresh-banner');

            // Wire close button after DOM insertion
            var closeBtn = document.getElementById('rrb-close-btn');
            if (closeBtn) closeBtn.addEventListener('click', _dismissBanner);

            // Auto-dismiss after 20 s if not acted on
            setTimeout(_dismissBanner, 20000);
        }

        // ── On Auth Success ───────────────────────────────────────────────
        async function _onAuthSuccess(user) {
            if (!user) return;
            // Guard against double-calls from onAuthStateChange
            if (window._authInProgress) return;
            window._authInProgress = true;
            window._authUser = user;

            // Fetch profile — wrapped in a plain Promise so it can never hang
            var profile = await new Promise(function (resolve) {
                var tid = setTimeout(function () { resolve(null); }, 5000);
                _postSupabase
                    .from('profiles')
                    .select('student_id, full_name, has_post_utme_access, streak_count, badges, is_admin, last_active, selected_university, post_utme_subjects')
                    .eq('id', user.id)
                    .maybeSingle()
                    .then(function (res) {
                        clearTimeout(tid);
                        resolve((res && res.data) ? res.data : null);
                    })
                    .catch(function () { clearTimeout(tid); resolve(null); });
            });

            // If trigger failed and there is no profile, create one now
            if (!profile) {
                await new Promise(function (resolve) {
                    var tid2 = setTimeout(resolve, 5000);
                    var sid = 'IOAU-' + String(1000 + Math.floor(Math.random() * 9000)).padStart(4, '0');
                    var name = (user.user_metadata && user.user_metadata.full_name) || 'Student';
                    _postSupabase.from('profiles').upsert(
                        {
                            id: user.id, email: user.email, student_id: sid,
                            full_name: name, has_post_utme_access: false
                        },
                        { onConflict: 'id', ignoreDuplicates: true }
                    ).select().maybeSingle()
                        .then(function (res) {
                            clearTimeout(tid2);
                            if (res && res.data) profile = res.data;
                            resolve();
                        })
                        .catch(function () { clearTimeout(tid2); resolve(); });
                });
            }

            window._authProfile = profile;
            window._authInProgress = false;
            if (profile && profile.is_admin) showAdminFab();

            // Fire-and-forget: update last_login
            _postSupabase.from('profiles')
                .update({ last_login: new Date().toISOString() })
                .eq('id', user.id).then(function () { }).catch(function () { });

            try { sessionStorage.removeItem('pwa_dismissed'); } catch(e) {}
            showPortalSelector();
            _showRefreshBanner();
        }


