        function showHubNotesList() {
            document.getElementById('hub-note-viewer').style.display = 'none';
            document.getElementById('hub-notes-screen').style.display = 'block';
        }

        async function openHubSubject(subject) {
            _hub.subject = subject;
            var label = subject.charAt(0).toUpperCase() + subject.slice(1);
            var uni   = (_putme.university) || (window._authProfile && window._authProfile.selected_university) || '';

            document.getElementById('hub-subject-screen').style.display = 'none';
            document.getElementById('hub-notes-screen').style.display   = 'block';
            document.getElementById('hub-notes-title').textContent      = (_hub.subjectIcons[subject]||'📖') + ' ' + label;
            document.getElementById('hub-notes-subtitle').textContent   = uni + ' \u00b7 Select a topic to begin';
            document.getElementById('hub-notes-list').innerHTML         = '<p style="text-align:center;color:#888;padding:20px;">Loading\u2026</p>';

            if (!_postSupabase) {
                document.getElementById('hub-notes-list').innerHTML = '<div class="hub-empty">Database not connected.</div>';
                return;
            }
            try {
                var res = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[], error:{message:'timeout'} }); }, 5000);
                    _postSupabase.from('study_materials')
                        .select('id, title, content, created_at')
                        .or('university.eq.' + uni + ',university.is.null')
                        .eq('subject', subject)
                        .order('created_at', { ascending:true })
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(){ clearTimeout(t); resolve({ data:[], error:{} }); });
                });
                _hub.notes = (res.data && res.data.length > 0) ? res.data : [];
                if (_hub.notes.length === 0) {
                    document.getElementById('hub-notes-list').innerHTML =
                        '<div class="hub-empty">📭 No study notes for <strong>' + label + '</strong> (' + uni + ') yet.<br><br>Add notes via the <strong>Admin Dashboard</strong>.</div>';
                    return;
                }
                document.getElementById('hub-notes-list').innerHTML = _hub.notes.map(function(n, i) {
                    return '<div class="hub-note-item" onclick="openNote(' + i + ')">' +
                        '<div style="font-weight:700;color:#1a2742;">' + (n.title||'Untitled') + '</div>' +
                        '<div style="font-size:0.75rem;color:#888;margin-top:3px;">' + new Date(n.created_at).toLocaleDateString('en-GB') + '</div>' +
                    '</div>';
                }).join('');
            } catch(e) {
                document.getElementById('hub-notes-list').innerHTML = '<div class="hub-empty">Could not load notes.</div>';
            }
        }

        function openNote(index) {
            var note = _hub.notes[index];
            if (!note) return;
            _hub.currentNote = note;
            document.getElementById('hub-notes-screen').style.display  = 'none';
            document.getElementById('hub-note-viewer').style.display   = 'block';
            document.getElementById('hub-viewer-title').textContent    = note.title || 'Note';
            document.getElementById('hub-viewer-sub').textContent      = _hub.subject.charAt(0).toUpperCase() + _hub.subject.slice(1);
            document.getElementById('hub-note-content').innerHTML      = note.content || '';
        }

        async function startKnowledgeQuiz() {
            var subject = _hub.subject;
            var uni     = (_putme.university) || (window._authProfile && window._authProfile.selected_university) || '';
            document.getElementById('hub-note-viewer').style.display = 'none';
            document.getElementById('hub-quiz-wrap').style.display   = 'block';
            document.getElementById('hub-quiz-title').textContent    = subject.charAt(0).toUpperCase() + subject.slice(1) + ' Quiz';
            document.getElementById('hub-quiz-done').style.display   = 'none';
            document.getElementById('hub-quiz-feedback').style.display = 'none';
            _hub.quizIndex   = 0;
            _hub.quizAnswers = {};
            _hub.quizQuestions = [];

            if (!_postSupabase) { document.getElementById('hub-quiz-question').textContent = 'No database connection.'; return; }
            try {
                var res = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[] }); }, 5000);
                    _postSupabase.from('question_bank')
                        .select('id, question, options, answer, explanation')
                        .eq('subject', subject)
                        .or('university.eq.' + uni + ',university.is.null')
                        .limit(50)
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                });
                var pool = res.data || [];
                if (pool.length === 0) {
                    document.getElementById('hub-quiz-question').textContent = 'No questions available for this subject yet.';
                    return;
                }
                pool.sort(function(){ return Math.random() - 0.5; });
                _hub.quizQuestions = pool.slice(0, Math.min(10, pool.length));
                renderHubQuizQuestion();
            } catch(e) {
                document.getElementById('hub-quiz-question').textContent = 'Could not load questions.';
            }
        }

        function renderHubQuizQuestion() {
            var total = _hub.quizQuestions.length;
            var i = _hub.quizIndex;
            var q = _hub.quizQuestions[i];
            document.getElementById('hub-quiz-progress').textContent = (i+1) + ' / ' + total;
            document.getElementById('hub-quiz-question').textContent = q.question;
            document.getElementById('hub-quiz-feedback').style.display = 'none';
            document.getElementById('hqb-next').style.display   = 'none';
            document.getElementById('hqb-finish').style.display = 'none';
            var labels = ['A','B','C','D'];
            document.getElementById('hub-quiz-opts').innerHTML = q.options.map(function(opt, oi) {
                return '<div class="hub-quiz-opt" id="hqopt-' + oi + '" onclick="selectHubQuizAnswer(' + oi + ')">' +
                    labels[oi] + '. ' + opt + '</div>';
            }).join('');
        }

        function selectHubQuizAnswer(oi) {
            var q = _hub.quizQuestions[_hub.quizIndex];
            _hub.quizAnswers[_hub.quizIndex] = oi;
            document.querySelectorAll('.hub-quiz-opt').forEach(function(el){ el.onclick = null; el.style.pointerEvents = 'none'; });
            document.getElementById('hqopt-' + oi).classList.add(oi === q.answer ? 'correct' : 'wrong');
            if (oi !== q.answer) document.getElementById('hqopt-' + q.answer).classList.add('correct');
            var fb = document.getElementById('hub-quiz-feedback');
            fb.style.display = 'block';
            fb.style.background = oi === q.answer ? '#d4edda' : '#f8d7da';
            fb.style.color      = oi === q.answer ? '#155724' : '#721c24';
            fb.innerHTML = (oi === q.answer ? '\u2705 Correct!' : '\u274C Wrong! Answer: <strong>' + ['A','B','C','D'][q.answer] + '</strong>') +
                (q.explanation ? '<br><span style="font-weight:400;font-size:0.85rem;">' + q.explanation + '</span>' : '');
            var isLast = _hub.quizIndex >= _hub.quizQuestions.length - 1;
            document.getElementById('hqb-next').style.display   = isLast ? 'none' : 'inline-block';
            document.getElementById('hqb-finish').style.display = isLast ? 'inline-block' : 'none';
        }

        function hubQuizNext() {
            _hub.quizIndex++;
            renderHubQuizQuestion();
        }

        function hubQuizFinish() {
            var correct = 0;
            _hub.quizQuestions.forEach(function(q, i) {
                if (_hub.quizAnswers[i] === q.answer) correct++;
            });
            var total = _hub.quizQuestions.length;
            document.getElementById('hub-quiz-opts').innerHTML     = '';
            document.getElementById('hub-quiz-feedback').style.display = 'none';
            document.getElementById('hub-quiz-done').style.display = 'block';
            document.getElementById('hub-done-score').textContent  = correct + '/' + total;
            document.getElementById('hub-done-msg').textContent    = correct === total ? 'Perfect! 🏆' : correct >= total*0.7 ? 'Great work! Keep it up.' : 'Keep studying and try again!';
        }

        function retryKnowledgeQuiz() {
            document.getElementById('hub-quiz-done').style.display = 'none';
            startKnowledgeQuiz();
        }

        function backToNoteViewer() {
            document.getElementById('hub-quiz-wrap').style.display  = 'none';
            document.getElementById('hub-note-viewer').style.display = 'block';
        }

        // ═════════════════════════════════════════════════════════════════════
        // GAMIFICATION — Streaks, Badges, Leaderboard, Sprint Challenge
        // ═════════════════════════════════════════════════════════════════════
        var BADGES_DEF = [
            { id:'first_exam',    icon:'🎯', label:'First Step',    desc:'Complete your first exam' },
            { id:'streak_3',      icon:'🔥', label:'On Fire',       desc:'3-day study streak' },
            { id:'streak_7',      icon:'\u26A1',     label:'Week Warrior',  desc:'7-day study streak' },
            { id:'perfect_score', icon:'💎', label:'Perfect Score', desc:'Score 100% on any exam' },
            { id:'sprint_3',      icon:'🚀', label:'Sprint Ace',    desc:'Complete 3 Sprint Challenges' },
            { id:'top_10',        icon:'🏆', label:'Top 10',        desc:'Reach the top 10 on the leaderboard' }
        ];

        var _sprint = {
            questions:[], index:0, answers:{}, correct:0,
            timerInterval:null, timeLeft:180, finished:false
        };

        function loadGameStats() {
            var profile = window._authProfile;
            if (!profile) return;
            var streak = profile.streak_count || 0;
            var earned = profile.badges || [];
            document.getElementById('streak-num').textContent = streak;
            var row = document.getElementById('badges-row');
            if (!row) return;
            row.innerHTML = earned.length === 0
                ? '<span style="font-size:0.78rem;opacity:0.7;">No badges yet \u2014 keep going!</span>'
                : earned.map(function(bid) {
                    var def = BADGES_DEF.find(function(b){ return b.id === bid; });
                    return def ? '<div class="badge-chip" title="' + def.desc + '">' + def.icon + ' ' + def.label + '</div>' : '';
                }).join('');
            document.getElementById('gami-bar').style.display = 'flex';
            fetchUserRank();
            loadMockEvents();
        }

        async function fetchUserRank() {
            if (!_postSupabase || !window._authUser) return;
            try {
                var res = await _postSupabase.from('post_utme_exams')
                    .select('student_id, score, total_questions')
                    .order('score', { ascending:false });
                if (!res.data || res.data.length === 0) return;
                var best = {};
                res.data.forEach(function(r) {
                    var pct = r.total_questions > 0 ? r.score/r.total_questions : 0;
                    if (!best[r.student_id] || pct > best[r.student_id]) best[r.student_id] = pct;
                });
                var sorted = Object.keys(best).sort(function(a,b){ return best[b]-best[a]; });
                var rank = sorted.indexOf(window._authUser.id) + 1;
                if (rank > 0) {
                    document.getElementById('rank-num').textContent = rank;
                    document.getElementById('rank-pill').style.display = 'flex';
                    if (rank <= 10) checkAndAwardBadge('top_10');
                }
            } catch(e) {}
        }

        async function checkAndAwardBadge(badgeId) {
            var profile = window._authProfile;
            if (!profile || !_postSupabase || !window._authUser) return;
            var earned = profile.badges || [];
            if (earned.indexOf(badgeId) !== -1) return;
            earned = earned.concat([badgeId]);
            try {
                var res = await _postSupabase.from('profiles')
                    .update({ badges: earned })
                    .eq('id', window._authUser.id)
                    .select('badges').maybeSingle();
                if (res && res.data) {
                    window._authProfile.badges = res.data.badges;
                    var def = BADGES_DEF.find(function(b){ return b.id === badgeId; });
                    if (def) showBadgeToast(def);
                    loadGameStats();
                }
            } catch(e) {}
        }

        function showBadgeToast(def) {
            var t = document.createElement('div');
            t.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#1a2742;color:#fff;padding:12px 20px;border-radius:12px;z-index:999999;font-weight:700;font-size:0.95rem;box-shadow:0 4px 16px rgba(0,0,0,0.3);text-align:center;';
            t.innerHTML = '🎉 Badge Unlocked: ' + def.icon + ' <strong>' + def.label + '</strong>';
            document.body.appendChild(t);
            setTimeout(function(){ t.remove(); }, 3500);
        }

        async function updateStreakAfterExam(pct) {
            if (!_postSupabase || !window._authUser) return;
            var today     = new Date().toISOString().slice(0,10);
            var yesterday = new Date(Date.now() - 86400000).toISOString().slice(0,10);
            try {
                var res = await _postSupabase.from('profiles')
                    .select('streak_count, last_active')
                    .eq('id', window._authUser.id).maybeSingle();
                if (!res || !res.data) return;
                var streak = res.data.streak_count || 0;
                var last   = res.data.last_active;
                if (last === today) { /* already counted */ }
                else if (last === yesterday) { streak += 1; }
                else { streak = 1; }
                await _postSupabase.from('profiles')
                    .update({ streak_count: streak, last_active: today })
                    .eq('id', window._authUser.id);
                if (window._authProfile) {
                    window._authProfile.streak_count = streak;
                    window._authProfile.last_active  = today;
                }
                loadGameStats();
                if (streak >= 3) checkAndAwardBadge('streak_3');
                if (streak >= 7) checkAndAwardBadge('streak_7');
                checkAndAwardBadge('first_exam');
                if (pct === 100) checkAndAwardBadge('perfect_score');
            } catch(e) {}
        }

        // ── Leaderboard ───────────────────────────────────────────────────────
        function openLeaderboard() {
            document.getElementById('post-utme-home').style.display = 'none';
            document.getElementById('leaderboard-screen').classList.add('active');
            loadLeaderboard('all', document.querySelector('#leaderboard-screen .lb-tab'));
        }
        function closeLeaderboard() {
            document.getElementById('leaderboard-screen').classList.remove('active');
            backToPutmeHome();
        }

        // Returns ISO-week Monday 00:00 and the following Monday 00:00 (UTC-aware via local)
        function _lbWeekBounds() {
            var now = new Date();
            var dow = now.getDay(); // 0=Sun
            var toMon = (dow === 0) ? -6 : (1 - dow);
            var mon = new Date(now);
            mon.setDate(now.getDate() + toMon);
            mon.setHours(0, 0, 0, 0);
            var nextMon = new Date(mon);
            nextMon.setDate(mon.getDate() + 7);
            var fmt = function(d) {
                return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short' });
            };
            return { start: mon.toISOString(), end: nextMon.toISOString(),
                     label: fmt(mon) + ' – ' + fmt(new Date(nextMon.getTime() - 86400000)) };
        }

        async function loadLeaderboard(mode, tabEl) {
            document.querySelectorAll('#leaderboard-screen .lb-tab').forEach(function(t){ t.classList.remove('active'); });
            if (tabEl) tabEl.classList.add('active');
            var listEl = document.getElementById('lb-list');
            listEl.innerHTML = '<div class="lb-empty">Loading…</div>';
            if (!_postSupabase) { listEl.innerHTML = '<div class="lb-empty">Not connected.</div>'; return; }
            try {
                var isWeeklyMock = (mode === 'weekly_mock');
                var weekBounds   = isWeeklyMock ? _lbWeekBounds() : null;

                // Query 1: exam rows (no FK join — avoids silent failures)
                var query = _postSupabase.from('post_utme_exams')
                    .select('student_id, score, total_questions, university, exam_mode, created_at')
                    .order('created_at', { ascending: false });

                if (mode === 'uni' && window._authProfile && window._authProfile.selected_university) {
                    query = query.eq('university', window._authProfile.selected_university);
                }
                if (isWeeklyMock) {
                    query = query.eq('exam_mode', 'mock')
                                 .gte('created_at', weekBounds.start)
                                 .lt('created_at', weekBounds.end);
                }

                var res = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[] }); }, 8000);
                    query.then(function(r){ clearTimeout(t); resolve(r); })
                         .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                });

                if (!res.data || res.data.length === 0) {
                    var emptyMsg = isWeeklyMock
                        ? '📅 No mock submissions this week yet. Check back after the next scheduled mock!'
                        : '📭 No results yet!';
                    listEl.innerHTML = '<div class="lb-empty">' + emptyMsg + '</div>';
                    return;
                }

                // DEDUPLICATE — keep each student's HIGHEST scoring exam only
                var bestMap = {};
                res.data.forEach(function(r) {
                    if (!r.student_id) return;
                    var pct = r.total_questions > 0 ? r.score / r.total_questions : 0;
                    if (!bestMap[r.student_id]) {
                        bestMap[r.student_id] = r;
                    } else {
                        var curPct = bestMap[r.student_id].total_questions > 0
                            ? bestMap[r.student_id].score / bestMap[r.student_id].total_questions : 0;
                        if (pct > curPct || (pct === curPct && r.score > bestMap[r.student_id].score)) {
                            bestMap[r.student_id] = r;
                        }
                    }
                });
                var unique = Object.values(bestMap);

                // Query 2: profiles for all unique student UUIDs
                var uids2 = unique.map(function(r){ return r.student_id; }).filter(Boolean);
                var profMap2 = {};
                if (uids2.length > 0) {
                    var profRes2 = await new Promise(function(resolve) {
                        var t2 = setTimeout(function(){ resolve({ data:[] }); }, 5000);
                        _postSupabase.from('profiles')
                            .select('id, full_name, student_id')
                            .in('id', uids2)
                            .then(function(r){ clearTimeout(t2); resolve(r); })
                            .catch(function(){ clearTimeout(t2); resolve({ data:[] }); });
                    });
                    (profRes2.data || []).forEach(function(p){ profMap2[p.id] = p; });
                }

                // Sort by percentage DESC, raw score as tiebreaker
                unique.sort(function(a, b) {
                    var pa = a.total_questions > 0 ? a.score / a.total_questions : 0;
                    var pb = b.total_questions > 0 ? b.score / b.total_questions : 0;
                    if (Math.abs(pb - pa) > 0.0001) return pb - pa;
                    return b.score - a.score;
                });

                var myId  = window._authUser ? window._authUser.id : null;
                var myIdx = myId ? unique.findIndex(function(r){ return r.student_id === myId; }) : -1;
                var top   = unique.slice(0, 30);

                // Week banner (Weekly Mocks only)
                var weekBannerHTML = '';
                if (isWeeklyMock && weekBounds) {
                    weekBannerHTML = '<div class="lb-week-banner">' +
                        '<span style="font-size:1.2rem;">📅</span>' +
                        '<div><strong>Weekly Mock Rankings</strong><br>' +
                        '<span style="opacity:0.85;">' + weekBounds.label + '</span></div>' +
                        '</div>';
                }

                // Your Rank card
                var yourRankHTML = '';
                if (myId && myIdx >= 0) {
                    var me     = unique[myIdx];
                    var myRank = myIdx + 1;
                    var myPct  = me.total_questions > 0 ? Math.round((me.score / me.total_questions) * 100) : 0;
                    var myPos  = myRank === 1 ? '🥇' : myRank === 2 ? '🥈' : myRank === 3 ? '🥉' : '#' + myRank;
                    var _meProf = profMap2[me.student_id] || {};
                    var myName = _meProf.full_name || 'You';
                    yourRankHTML =
                        '<div class="lb-my-rank-card">' +
                            '<div><div class="lb-my-rank-label">Your Rank</div>' +
                            '<div class="lb-my-rank-pos">' + myPos + '</div></div>' +
                            '<div class="lb-my-rank-details">' +
                                '<div class="lb-my-rank-name">' + myName + '</div>' +
                                '<div class="lb-my-rank-score">' + me.score + '/' + me.total_questions + ' · ' + myPct + '%' +
                                    (myRank > 30 ? ' · outside top 30' : '') + '</div>' +
                            '</div>' +
                        '</div>';
                } else if (myId && myIdx === -1 && isWeeklyMock) {
                    yourRankHTML = '<div class="lb-my-rank-card" style="background:linear-gradient(135deg,#4b5563,#374151);">' +
                        '<span style="font-size:1.4rem;">📋</span>' +
                        '<div class="lb-my-rank-details">' +
                            '<div class="lb-my-rank-name">You haven\'t submitted a mock this week</div>' +
                            '<div class="lb-my-rank-score">Join a scheduled mock exam to appear here!</div>' +
                        '</div></div>';
                }

                var countLine = '<div class="lb-count-line">' + unique.length +
                    ' student' + (unique.length !== 1 ? 's' : '') +
                    (isWeeklyMock ? ' participated this week' : ' ranked') + '</div>';

                listEl.innerHTML = weekBannerHTML + yourRankHTML + countLine + top.map(function(r, i) {
                    var rank      = i + 1;
                    var pct       = r.total_questions > 0 ? Math.round((r.score / r.total_questions) * 100) : 0;
                    var rankEmoji = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : rank;
                    var rankClass = rank <= 3 ? ['gold','silver','bronze'][rank-1] : '';
                    var isMe      = r.student_id === myId;
                    var _lbProf   = profMap2[r.student_id] || {};
                    var name      = _lbProf.full_name || 'Student';
                    var sid       = _lbProf.student_id || '—';
                    var dateStr   = r.created_at ? new Date(r.created_at).toLocaleDateString('en-GB', { day:'2-digit', month:'short' }) : '';
                    return '<div class="lb-row' + (isMe ? ' lb-me' : '') + '">' +
                        '<div class="lb-rank ' + rankClass + '">' + rankEmoji + '</div>' +
                        '<div class="lb-info">' +
                            '<div class="lb-name">' + name + (isMe ? ' <span style="color:#0056b3;font-size:0.75rem;">(You)</span>' : '') + '</div>' +
                            '<div class="lb-sid">' + sid + ' · ' + (r.university || '—') + (dateStr ? ' · ' + dateStr : '') + '</div>' +
                        '</div>' +
                        '<div class="lb-score-box">' +
                            '<div class="lb-score">' + r.score + '/' + r.total_questions + '</div>' +
                            '<div class="lb-pct">' + pct + '%</div>' +
                        '</div>' +
                    '</div>';
                }).join('');
            } catch(e) { listEl.innerHTML = '<div class="lb-empty">Could not load leaderboard.</div>'; }
        }

        // ── Sprint Challenge ──────────────────────────────────────────────────
        function startSprintChallenge() {
            if (!_putme.subjects || _putme.subjects.length === 0) {
                alert('Please select your subjects first by starting a Practice or Mock exam.');
                return;
            }
            _sprint = { questions:[], index:0, answers:{}, correct:0, timerInterval:null, timeLeft:180, finished:false };
            document.getElementById('post-utme-home').style.display = 'none';
            document.getElementById('sprint-screen').classList.add('active');
            document.getElementById('sprint-intro').style.display     = 'block';
            document.getElementById('sprint-quiz-area').style.display = 'none';
            document.getElementById('sprint-result').style.display    = 'none';
            document.getElementById('sprint-timer').textContent       = '3:00';
            document.getElementById('sprint-timer').classList.remove('urgent');
            var best  = localStorage.getItem('sprint_best_' + (window._authUser ? window._authUser.id : 'guest'));
            document.getElementById('sprint-best-display').textContent = best ? '🏅 Your best: ' + best + '/10' : '';
        }

        function exitSprint() {
            clearInterval(_sprint.timerInterval);
            document.getElementById('sprint-screen').classList.remove('active');
        }

        async function launchSprint() {
            clearInterval(_sprint.timerInterval);
            document.getElementById('sprint-intro').style.display     = 'none';
            document.getElementById('sprint-result').style.display    = 'none';
            document.getElementById('sprint-quiz-area').style.display = 'block';
            var subjects = _putme.subjects.slice();
            var uni = (window._authProfile && window._authProfile.selected_university) || (_putme.university || '');
            var allQs = [];
            if (_postSupabase) {
                try {
                    var res = await new Promise(function(resolve) {
                        var t = setTimeout(function(){ resolve({ data:[] }); }, 6000);
                        _postSupabase.from('question_bank')
                            .select('id, subject, question, option_a, option_b, option_c, option_d, correct_answer, explanation')
                            .in('subject', subjects)
                            .or('university.eq.' + uni + ',university.is.null,university.eq.ALL')
                            .limit(100)
                            .then(function(r){ clearTimeout(t); resolve(r); })
                            .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                    });
                    allQs = (res.data || []).map(function(q) {
                        return {
                            id: q.id, subject: q.subject, question: q.question,
                            options: [q.option_a, q.option_b, q.option_c, q.option_d],
                            answer: ['A','B','C','D'].indexOf((q.correct_answer||'').toUpperCase()),
                            explanation: q.explanation
                        };
                    });
                } catch(e) {}
            }
            if (allQs.length < 5) {
                alert('Not enough questions yet. Add questions to the question bank first.');
                document.getElementById('sprint-intro').style.display     = 'block';
                document.getElementById('sprint-quiz-area').style.display = 'none';
                return;
            }
            allQs.sort(function(){ return Math.random()-0.5; });
            _sprint.questions = allQs.slice(0,10);
            _sprint.index = 0; _sprint.answers = {}; _sprint.correct = 0;
            _sprint.finished = false; _sprint.timeLeft = 180;
            renderSprintQuestion();
            sprintTimerStart();
        }

        function sprintTimerStart() {
            clearInterval(_sprint.timerInterval);
            _sprint.timerInterval = setInterval(function() {
                _sprint.timeLeft--;
                var m = Math.floor(_sprint.timeLeft/60), s = _sprint.timeLeft%60;
                var el = document.getElementById('sprint-timer');
                el.textContent = m + ':' + (s < 10 ? '0' : '') + s;
                if (_sprint.timeLeft <= 30) el.classList.add('urgent');
                if (_sprint.timeLeft <= 0) { clearInterval(_sprint.timerInterval); finishSprint(); }
            }, 1000);
        }

        function renderSprintQuestion() {
            var i = _sprint.index, q = _sprint.questions[i], total = _sprint.questions.length;
            document.getElementById('sprint-q-num').textContent = (i+1) + ' / ' + total;
            document.getElementById('sprint-prog-fill').style.width = Math.round((i/total)*100) + '%';
            document.getElementById('sprint-q-text').textContent = q.question;
            document.getElementById('sprint-next-btn').style.display = 'none';
            var labels = ['A','B','C','D'];
            document.getElementById('sprint-opts').innerHTML = (q.options||[]).slice(0,4).map(function(opt,oi) {
                return '<button class="sprint-opt" id="sopt-' + oi + '" onclick="selectSprintOpt(' + oi + ')">' + labels[oi] + '. ' + opt + '</button>';
            }).join('');
        }

        function selectSprintOpt(oi) {
            var q = _sprint.questions[_sprint.index];
            _sprint.answers[_sprint.index] = ['A','B','C','D'][oi];
            document.querySelectorAll('.sprint-opt').forEach(function(b){ b.onclick = null; b.classList.remove('selected'); });
            document.getElementById('sopt-' + oi).classList.add('selected');
            document.getElementById('sopt-' + oi).classList.add(oi === q.answer ? 'correct' : 'wrong');
            if (oi !== q.answer) document.getElementById('sopt-' + q.answer).classList.add('correct');
            else _sprint.correct++;
            document.getElementById('sprint-next-btn').style.display = 'block';
            document.getElementById('sprint-next-btn').textContent = (_sprint.index >= _sprint.questions.length-1) ? 'Finish \u2192' : 'Next \u2192';
        }

        function sprintNext() {
            _sprint.index++;
            if (_sprint.index >= _sprint.questions.length) finishSprint();
            else renderSprintQuestion();
        }

        function finishSprint() {
            clearInterval(_sprint.timerInterval);
            if (_sprint.finished) return;
            _sprint.finished = true;
            var score = _sprint.correct, total = _sprint.questions.length;
            var pct   = total > 0 ? Math.round((score/total)*100) : 0;
            var grade = pct===100 ? '💎 Perfect!' : pct>=70 ? '🔥 Excellent!' : pct>=50 ? '👍 Good Job!' : '📚 Keep Practicing!';
            document.getElementById('sprint-quiz-area').style.display = 'none';
            document.getElementById('sprint-result').style.display    = 'block';
            document.getElementById('sprint-result-score').textContent = score + '/' + total;
            document.getElementById('sprint-result-grade').textContent = grade;
            var key  = 'sprint_best_' + (window._authUser ? window._authUser.id : 'guest');
            var prev = parseInt(localStorage.getItem(key)||'0',10);
            var bestEl = document.getElementById('sprint-result-best');
            if (score > prev) { localStorage.setItem(key,score); bestEl.textContent = '🎉 New Personal Best!'; }
            else { bestEl.textContent = '🏅 Your best: ' + prev + '/10'; }
            var countKey = 'sprint_count_' + (window._authUser ? window._authUser.id : 'guest');
            var cnt = parseInt(localStorage.getItem(countKey)||'0',10) + 1;
            localStorage.setItem(countKey, cnt);
            if (cnt >= 3) checkAndAwardBadge('sprint_3');
            document.getElementById('sprint-timer').textContent = '0:00';
        }

        // ── My History ────────────────────────────────────────────────────────
        async function openMyHistory() {
            if (!_postSupabase || !window._authUser) { alert('Please sign in to view history.'); return; }
            var overlay = document.createElement('div');
            overlay.id = 'my-hist-overlay';
            overlay.style.cssText = 'position:fixed;inset:0;background:var(--bg,#f4f7fb);z-index:99999;overflow-y:auto;';
            var header = document.createElement('div');
            header.style.cssText = 'background:linear-gradient(135deg,#1a2742,#0056b3);color:#fff;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;';
            header.innerHTML = '<h2 style="margin:0;font-size:1.2rem;">📊 My Exam History</h2>';
            var backBtn = document.createElement('button');
            backBtn.textContent = '\u2190 Back';
            backBtn.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;padding:6px 14px;border-radius:20px;cursor:pointer;font-size:0.85rem;';
            backBtn.onclick = function(){ document.getElementById('my-hist-overlay').remove(); };
            header.appendChild(backBtn);
            var body = document.createElement('div');
            body.id = 'history-body';
            body.style.cssText = 'max-width:700px;margin:0 auto;padding:20px 16px;';
            body.innerHTML = '<p style="text-align:center;color:#888;padding:30px;">Loading\u2026</p>';
            overlay.appendChild(header);
            overlay.appendChild(body);
            document.body.appendChild(overlay);
            try {
                var res = await _postSupabase.from('post_utme_exams')
                    .select('university, subjects, exam_mode, score, total_questions, time_taken, created_at')
                    .eq('student_id', window._authUser.id)
                    .order('created_at', { ascending:false }).limit(30);
                var rows = (res && res.data) ? res.data : [];
                if (rows.length === 0) {
                    body.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">No exams taken yet. Start a Mock Exam!</div>'; return;
                }
                body.innerHTML = rows.map(function(r) {
                    var pct   = r.total_questions > 0 ? Math.round((r.score/r.total_questions)*100) : 0;
                    var color = pct >= 70 ? '#28a745' : pct >= 50 ? '#0056b3' : '#dc3545';
                    var date  = new Date(r.created_at).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
                    var m = Math.floor((r.time_taken||0)/60), s = (r.time_taken||0)%60;
                    return '<div style="background:#fff;border-radius:12px;padding:14px 18px;margin-bottom:10px;box-shadow:0 1px 4px rgba(0,0,0,0.07);display:flex;align-items:center;gap:14px;">' +
                        '<div style="font-size:2rem;font-weight:900;color:' + color + ';min-width:52px;text-align:center;">' + pct + '%</div>' +
                        '<div style="flex:1;"><div style="font-weight:700;color:#1a2742;font-size:0.95rem;">' + r.university + ' \u00b7 ' + (r.exam_mode==='mock'?'Mock Exam':'Practice') + '</div>' +
                        '<div style="font-size:0.78rem;color:#888;margin-top:2px;">' + (r.subjects||[]).join(', ') + '</div>' +
                        '<div style="font-size:0.75rem;color:#aaa;margin-top:2px;">' + date + ' \u00b7 ' + m + 'm ' + s + 's</div></div>' +
                        '<div style="text-align:right;"><div style="font-size:1rem;font-weight:700;color:' + color + ';">' + r.score + '/' + r.total_questions + '</div></div></div>';
                }).join('');
            } catch(e) { body.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Could not load history.</div>'; }
        }


        // ── Performance Analytics Hub ─────────────────────────────────────────
        async function openAnalyticsHub() {
            if (!_postSupabase || !window._authUser) { alert('Please sign in to view analytics.'); return; }

            var overlay = document.createElement('div');
            overlay.id = 'analytics-overlay';
            overlay.style.cssText = 'position:fixed;inset:0;background:var(--bg,#f4f7fb);z-index:99999;overflow-y:auto;';

            var header = document.createElement('div');
            header.style.cssText = 'background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;';
            header.innerHTML = '<h2 style="margin:0;font-size:1.2rem;">📈 Performance Analytics</h2>';
            var backBtn = document.createElement('button');
            backBtn.textContent = '← Back';
            backBtn.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;padding:6px 14px;border-radius:20px;cursor:pointer;font-size:0.85rem;';
            backBtn.onclick = function() { var el = document.getElementById('analytics-overlay'); if (el) el.remove(); };
            header.appendChild(backBtn);

            var body = document.createElement('div');
            body.id = 'analytics-body';
            body.style.cssText = 'max-width:700px;margin:0 auto;padding:20px 16px;';
            body.innerHTML = '<p style="text-align:center;color:#888;padding:30px;">Loading…</p>';

            overlay.appendChild(header);
            overlay.appendChild(body);
            document.body.appendChild(overlay);

            try {
                var res = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[] }); }, 8000);
                    _postSupabase.from('post_utme_exams')
                        .select('score, total_questions, subjects, exam_mode, time_taken, created_at, university')
                        .eq('student_id', window._authUser.id)
                        .order('created_at', { ascending: false })
                        .limit(50)
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                });

                var rows = (res && res.data) ? res.data : [];
                if (rows.length === 0) {
                    body.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#888;">' +
                        '<div style="font-size:3rem;">📭</div>' +
                        '<p>No exams yet.<br>Start a Practice or Mock exam to see your analytics!</p></div>';
                    return;
                }

                // ── Compute summary stats ──
                var total       = rows.length;
                var pcts        = rows.map(function(r){ return r.total_questions > 0 ? (r.score / r.total_questions) * 100 : 0; });
                var avg         = Math.round(pcts.reduce(function(a, b){ return a + b; }, 0) / pcts.length);
                var best        = Math.round(Math.max.apply(null, pcts));
                var mockCount   = rows.filter(function(r){ return r.exam_mode === 'mock'; }).length;
                var practiceCount = total - mockCount;

                // ── Score trend: last 10 exams in chronological order ──
                var trend = rows.slice(0, 10).reverse();

                // ── Last 5 exams (newest first) ──
                var recent5 = rows.slice(0, 5);

                // ── Build HTML ──
                var html = '';

                // Stats row
                var statsData = [
                    { icon: '📝', label: 'Total Exams', val: total },
                    { icon: '📊', label: 'Avg Score',   val: avg + '%' },
                    { icon: '🏆', label: 'Best Score',  val: best + '%' }
                ];
                html += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px;">';
                statsData.forEach(function(s) {
                    html += '<div style="background:#fff;border-radius:14px;padding:16px 10px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,0.07);">' +
                        '<div style="font-size:1.5rem;">' + s.icon + '</div>' +
                        '<div style="font-size:1.5rem;font-weight:900;color:#1a2742;margin:4px 0;">' + s.val + '</div>' +
                        '<div style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.05em;">' + s.label + '</div>' +
                        '</div>';
                });
                html += '</div>';

                // Mode breakdown
                html += '<div style="display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap;">' +
                    '<span style="background:#e8f4fd;color:#0056b3;border-radius:20px;padding:5px 14px;font-size:0.8rem;font-weight:700;">🎯 ' + practiceCount + ' Practice</span>' +
                    '<span style="background:#f3e8ff;color:#7c3aed;border-radius:20px;padding:5px 14px;font-size:0.8rem;font-weight:700;">📅 ' + mockCount + ' Mock</span>' +
                    '</div>';

                // Score trend bar chart
                if (trend.length > 1) {
                    html += '<div style="background:#fff;border-radius:14px;padding:16px;margin-bottom:18px;box-shadow:0 1px 4px rgba(0,0,0,0.07);">' +
                        '<div style="font-weight:700;color:#1a2742;margin-bottom:12px;font-size:0.88rem;">📈 Score Trend — Last ' + trend.length + ' Exams</div>' +
                        '<div style="display:flex;align-items:flex-end;gap:5px;height:90px;padding-bottom:4px;">';
                    trend.forEach(function(r, i) {
                        var p   = r.total_questions > 0 ? Math.round((r.score / r.total_questions) * 100) : 0;
                        var bh  = Math.max(8, Math.round((p / 100) * 70));
                        var col = p >= 70 ? '#28a745' : p >= 50 ? '#0056b3' : '#dc3545';
                        var isLatest = (i === trend.length - 1);
                        var dt  = new Date(r.created_at).toLocaleDateString('en-GB', { day:'2-digit', month:'short' });
                        html += '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;">' +
                            '<div style="font-size:0.58rem;color:#888;font-weight:700;">' + p + '%</div>' +
                            '<div title="' + dt + '" style="width:100%;height:' + bh + 'px;background:' + col + ';border-radius:4px 4px 0 0;opacity:' + (isLatest ? '1' : '0.65') + ';transition:opacity 0.2s;"></div>' +
                            '<div style="font-size:0.55rem;color:#aaa;white-space:nowrap;overflow:hidden;max-width:100%;text-align:center;">' + dt + '</div>' +
                            '</div>';
                    });
                    html += '</div></div>';
                }

                // Last 5 exams heading
                html += '<div style="font-weight:700;color:#1a2742;margin-bottom:10px;font-size:0.88rem;">🕒 Last 5 Exams</div>';
                recent5.forEach(function(r) {
                    var p    = r.total_questions > 0 ? Math.round((r.score / r.total_questions) * 100) : 0;
                    var col  = p >= 70 ? '#28a745' : p >= 50 ? '#0056b3' : '#dc3545';
                    var date = new Date(r.created_at).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });
                    var mins = Math.floor((r.time_taken || 0) / 60);
                    var secs = (r.time_taken || 0) % 60;
                    var modeLabel = r.exam_mode === 'mock' ? '📅 Mock' : '🎯 Practice';
                    html += '<div style="background:#fff;border-radius:12px;padding:14px 16px;margin-bottom:8px;box-shadow:0 1px 4px rgba(0,0,0,0.07);">' +
                        '<div style="display:flex;align-items:center;gap:12px;">' +
                        '<div style="font-size:1.8rem;font-weight:900;color:' + col + ';min-width:52px;text-align:center;line-height:1;">' + p + '%</div>' +
                        '<div style="flex:1;min-width:0;">' +
                        '<div style="font-weight:700;color:#1a2742;font-size:0.9rem;">' + modeLabel + ' · ' + (r.university || '—') + '</div>' +
                        '<div style="font-size:0.77rem;color:#555;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + (r.subjects || []).join(' · ') + '</div>' +
                        '<div style="font-size:0.72rem;color:#aaa;margin-top:2px;">' + date + (r.time_taken ? ' · ' + mins + 'm ' + secs + 's' : '') + '</div>' +
                        '</div>' +
                        '<div style="font-size:1rem;font-weight:800;color:' + col + ';white-space:nowrap;">' + r.score + '/' + r.total_questions + '</div>' +
                        '</div></div>';
                });

                body.innerHTML = html;
            } catch(e) {
                body.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Could not load analytics.</div>';
            }
        }

        // ═════════════════════════════════════════════════════════════════════
        // SCHEDULED MOCK EVENTS
        // ═════════════════════════════════════════════════════════════════════
        var _mockCountdownTimers = [];

        function getMockStatus(mock) {
            var now   = Date.now();
            var start = new Date(mock.scheduled_at).getTime();
            var end   = start + (mock.duration_minutes * 60000);
            if (now < start)             return 'upcoming';
            if (now >= start && now < end) return 'live';
            return 'ended';
        }

        async function loadMockEvents() {
            var section = document.getElementById('mock-events-section');
            if (!section || !_postSupabase) return;
            try {
                var uni = (_putme.university) || (window._authProfile && window._authProfile.selected_university) || '';
                var res = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[] }); }, 5000);
                    var q = _postSupabase.from('scheduled_mocks').select('*').order('scheduled_at', { ascending:true });
                    if (uni) q = q.or('university.is.null,university.eq.' + uni);
                    else     q = q.is('university', null);
                    q.then(function(r){ clearTimeout(t); resolve(r); })
                     .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                });
                var mocks = (res.data || []).filter(function(m) {
                    var end = new Date(m.scheduled_at).getTime() + m.duration_minutes * 60000;
                    return Date.now() < end + 7200000;
                });
                if (mocks.length === 0) { section.style.display = 'none'; return; }

                // Fetch which mock IDs the current user has already submitted
                var takenIds = {};
                if (window._authUser) {
                    var takenRes = await new Promise(function(resolve) {
                        var t2 = setTimeout(function(){ resolve({ data:[] }); }, 4000);
                        _postSupabase.from('post_utme_exams')
                            .select('mock_event_id')
                            .eq('student_id', window._authUser.id)
                            .not('mock_event_id', 'is', null)
                            .then(function(r){ clearTimeout(t2); resolve(r); })
                            .catch(function(){ clearTimeout(t2); resolve({ data:[] }); });
                    });
                    (takenRes.data || []).forEach(function(row){
                        if (row.mock_event_id) takenIds[row.mock_event_id] = true;
                    });
                }
                window._takenMockIds = takenIds;

                section.style.display = 'block';
                renderMockEventCards(mocks, section);
            } catch(e) { section.style.display = 'none'; }
        }

        function renderMockEventCards(mocks, container) {
            _mockCountdownTimers.forEach(clearInterval);
            _mockCountdownTimers = [];
            window._liveMocks = mocks;
            container.innerHTML = '';
            mocks.forEach(function(mock, idx) {
                var status    = getMockStatus(mock);
                var uniTag    = mock.university || 'All Universities';
                var startDate = new Date(mock.scheduled_at);
                var dateStr   = startDate.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'}) +
                                ' at ' + startDate.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
                var card = document.createElement('div');
                card.className = 'mock-event-card ' + status;
                var info = document.createElement('div');
                info.className = 'mock-event-info';
                var _qps = mock.questions_per_subject || 20;
                info.innerHTML = '<div class="mock-event-title">' + (mock.title||'Mock Exam') + '</div>' +
                    '<div class="mock-event-meta">' + uniTag + ' \u2022 ' + dateStr + ' \u2022 ' + mock.duration_minutes + ' min \u2022 ' + _qps + ' Qs/subject</div>' +
                    (mock.description ? '<div class="mock-event-meta" style="margin-top:3px;font-style:italic;">' + mock.description + '</div>' : '');
                var right = document.createElement('div');
                right.className = 'mock-event-right';
                if (status === 'live') {
                    var liveWrap = document.createElement('div');
                    var badge = document.createElement('div');
                    badge.className = 'mock-live-badge'; badge.textContent = 'LIVE NOW';
                    liveWrap.appendChild(badge);
                    liveWrap.appendChild(document.createElement('br'));
                    var _alreadyTaken = window._takenMockIds && window._takenMockIds[mock.id];
                    if (_alreadyTaken) {
                        var takenBadge = document.createElement('div');
                        takenBadge.style.cssText = 'margin-top:6px;padding:6px 14px;background:#e8f5e9;color:#2e7d32;border-radius:8px;font-size:0.8rem;font-weight:600;';
                        takenBadge.textContent = '\u2713 Already Submitted';
                        var viewAgain = document.createElement('button');
                        viewAgain.className = 'admin-view-btn'; viewAgain.textContent = 'View Results';
                        viewAgain.style.marginTop = '4px';
                        viewAgain.onclick = (function(i){ return function(){ var mx=window._liveMocks[i]; openMockLeaderboard(mx.id,mx.title||'Mock Event'); }; })(idx);
                        liveWrap.appendChild(takenBadge);
                        liveWrap.appendChild(viewAgain);
                    } else {
                        var joinBtn = document.createElement('button');
                        joinBtn.className = 'mock-join-btn'; joinBtn.textContent = 'Join Now \u2192';
                        joinBtn.style.marginTop = '6px';
                        joinBtn.onclick = (function(i){ return function(){ var mx=window._liveMocks[i]; joinMockExam(mx.id,mx.title||'Mock Event',mx.duration_minutes, mx.questions_per_subject||20); }; })(idx);
                        liveWrap.appendChild(joinBtn);
                    }
                    right.appendChild(liveWrap);
                } else if (status === 'upcoming') {
                    var cd = document.createElement('div');
                    cd.className = 'mock-countdown'; cd.textContent = '--:--:--';
                    right.appendChild(cd);
                    var timer = setInterval(function() {
                        var diff = new Date(mock.scheduled_at).getTime() - Date.now();
                        if (diff <= 0) { clearInterval(timer); loadMockEvents(); return; }
                        var h=Math.floor(diff/3600000), mn=Math.floor((diff%3600000)/60000), sc=Math.floor((diff%60000)/1000);
                        var pad=function(n){return n<10?'0'+n:''+n;};
                        cd.textContent=(h>0?pad(h)+':':'')+pad(mn)+':'+pad(sc);
                    }, 1000);
                    _mockCountdownTimers.push(timer);
                } else {
                    var viewBtn = document.createElement('button');
                    viewBtn.className = 'admin-view-btn'; viewBtn.textContent = 'View Results';
                    viewBtn.onclick = (function(i){ return function(){ var mx=window._liveMocks[i]; openMockLeaderboard(mx.id,mx.title||'Mock Event'); }; })(idx);
                    right.appendChild(viewBtn);
                }
                card.appendChild(info); card.appendChild(right); container.appendChild(card);
            });
        }

        function joinMockExam(mockId, mockTitle, durationMin, questionsPerSub) {
            // Hard guard: prevent re-entry if student already submitted this mock
            if (window._takenMockIds && window._takenMockIds[mockId]) {
                if (confirm('You have already submitted this mock exam.\nWould you like to view the leaderboard?')) {
                    openMockLeaderboard(mockId, mockTitle);
                }
                return;
            }
            if (!_putme.subjects || _putme.subjects.length < 4) {
                // Save mock details so confirmSubjectsAndStart can apply them after subject selection
                _putme._pendingMockId        = mockId;
                _putme._pendingMockTitle     = mockTitle;
                _putme._pendingMockDuration  = durationMin;
                _putme._pendingMockQuestions = questionsPerSub || 20;
                openSubjectModal('mock');
                return;
            }
            // Subjects already set — wire mock metadata then launch directly
            _putme.mockEventId         = mockId;
            _putme.mockTitle           = mockTitle;
            _putme.mode                = 'mock';
            _putme.customDuration      = durationMin * 60;
            _putme.questionsPerSubject = questionsPerSub || 20;
            // Durable window-level copies so the event ID/title survive any _putme mutation
            window.currentEventId    = mockId;
            window.currentEventTitle = mockTitle;
            startPutmeExam(_putme.subjects, 'mock', _selectedUni || _putme.university || 'OAU');
        }

        async function openMockLeaderboard(mockId, mockTitle) {
            var overlay = document.getElementById('mock-lb-overlay');
            overlay.classList.add('active');
            document.getElementById('mock-lb-event-title').textContent = mockTitle || 'Mock Event';
            var listEl = document.getElementById('mock-lb-list');
            listEl.innerHTML = '<div class="lb-empty">Loading…</div>';
            if (!_postSupabase) { listEl.innerHTML = '<div class="lb-empty">Not connected.</div>'; return; }
            try {
                // Query 1: exam rows for this mock (no FK join needed)
                var examsRes = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:[] }); }, 6000);
                    _postSupabase.from('post_utme_exams')
                        .select('student_id, score, total_questions')
                        .eq('mock_event_id', mockId)
                        .order('score', { ascending: false })
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(){ clearTimeout(t); resolve({ data:[] }); });
                });
                var rows = examsRes.data || [];
                if (rows.length === 0) { listEl.innerHTML = '<div class="lb-empty">No submissions yet.</div>'; return; }

                // Query 2: look up profiles separately by UUID list
                var uids = rows.map(function(r){ return r.student_id; }).filter(Boolean);
                var profileMap = {};
                if (uids.length > 0) {
                    var profRes = await new Promise(function(resolve) {
                        var t2 = setTimeout(function(){ resolve({ data:[] }); }, 5000);
                        _postSupabase.from('profiles')
                            .select('id, full_name, student_id')
                            .in('id', uids)
                            .then(function(r){ clearTimeout(t2); resolve(r); })
                            .catch(function(){ clearTimeout(t2); resolve({ data:[] }); });
                    });
                    (profRes.data || []).forEach(function(p){ profileMap[p.id] = p; });
                }

                var myId = window._authUser ? window._authUser.id : null;
                listEl.innerHTML = rows.map(function(r, i) {
                    var rank = i + 1;
                    var pct  = r.total_questions > 0 ? Math.round((r.score / r.total_questions) * 100) : 0;
                    var rankEmoji = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : rank;
                    var rankClass = rank <= 3 ? ['gold','silver','bronze'][rank-1] : '';
                    var isMe = r.student_id === myId;
                    var prof = profileMap[r.student_id] || {};
                    var name = prof.full_name || 'Student';
                    var sid  = prof.student_id || '—';
                    return '<div class="lb-row' + (isMe ? ' lb-me' : '') + '">' +
                        '<div class="lb-rank ' + rankClass + '">' + rankEmoji + '</div>' +
                        '<div class="lb-info"><div class="lb-name">' + name +
                            (isMe ? ' <span style="color:#0056b3;font-size:0.75rem;">(You)</span>' : '') +
                        '</div><div class="lb-sid">' + sid + '</div></div>' +
                        '<div class="lb-score-box"><div class="lb-score">' + r.score + '/' + r.total_questions + '</div>' +
                        '<div class="lb-pct">' + pct + '%</div></div></div>';
                }).join('');
            } catch(e) { listEl.innerHTML = '<div class="lb-empty">Could not load results.</div>'; }
        }

