        async function adminSendTestEmail() {
            var testEmail = (document.getElementById('adm-camp-test-email').value || '').trim();
            var subject   = (document.getElementById('adm-camp-subject').value || '').trim();
            var whatsapp  = (document.getElementById('adm-camp-whatsapp').value || '').trim();
            var msgEl     = document.getElementById('adm-camp-msg');
            var testBtn   = document.getElementById('adm-camp-test-btn');
            if (!testEmail) { alert('Enter a test email address.'); return; }
            if (!subject)   { alert('Enter a subject line.'); return; }
            var htmlContent = buildCampaignHtml(whatsapp);
            msgEl.style.display = 'block';
            msgEl.style.background = '#f0f0ff';
            msgEl.style.color = '#374151';
            msgEl.textContent = '⏳ Sending test…';
            testBtn.disabled = true;
            try {
                var session = await _postSupabase.auth.getSession();
                var token   = session && session.data && session.data.session && session.data.session.access_token;
                if (!token) throw new Error('Not logged in.');
                var res  = await fetch('/api/send-campaign', {
                    method:  'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                    body:    JSON.stringify({ subject: subject, htmlContent: htmlContent, testEmail: testEmail }),
                });
                var data = await res.json();
                if (!res.ok) throw new Error(data.error || 'Unknown error.');
                msgEl.style.background = '#d1fae5';
                msgEl.style.color      = '#065f46';
                msgEl.textContent      = '✅ Test email sent to ' + testEmail + ' — check the inbox!';
            } catch(e) {
                msgEl.style.background = '#fee2e2';
                msgEl.style.color      = '#991b1b';
                msgEl.textContent      = '❌ ' + e.message;
            } finally {
                testBtn.disabled = false;
            }
        }

        function adminPreviewCampaign() {
            var whatsapp = (document.getElementById('adm-camp-whatsapp').value || '').trim();
            if (!whatsapp) { alert('Enter your WhatsApp number first.'); return; }
            var html     = buildCampaignHtml(whatsapp);
            var preview  = document.getElementById('adm-camp-preview');
            var iframe   = document.getElementById('adm-camp-iframe');
            preview.style.display = 'block';
            // Replace {{params.name}} with a demo name for preview
            var previewHtml = html.replace(/\{\{params\.name\}\}/g, 'Oluwaseun');
            iframe.srcdoc = previewHtml;
        }

        async function adminSendCampaign() {
            var subject  = (document.getElementById('adm-camp-subject').value  || '').trim();
            var whatsapp = (document.getElementById('adm-camp-whatsapp').value || '').trim();
            var msgEl    = document.getElementById('adm-camp-msg');
            var sendBtn  = document.getElementById('adm-camp-send-btn');

            if (!subject)  { alert('Please enter an email subject.'); return; }
            if (!whatsapp) { alert('Please enter your WhatsApp number.'); return; }

            if (!confirm('Send this campaign to ALL free-tier students now?\n\nEach student will receive a personalised email. This cannot be undone.')) return;

            var htmlContent = buildCampaignHtml(whatsapp);

            msgEl.style.display = 'block';
            msgEl.style.background = '#f0f0ff';
            msgEl.style.color = '#374151';
            msgEl.textContent = '⏳ Sending… please wait.';
            sendBtn.disabled = true;

            try {
                var session = await _postSupabase.auth.getSession();
                var token   = session && session.data && session.data.session && session.data.session.access_token;
                if (!token) throw new Error('Not logged in.');

                var res = await fetch('/api/send-campaign', {
                    method:  'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                    body:    JSON.stringify({ subject: subject, htmlContent: htmlContent }),
                });
                var data = await res.json();
                if (!res.ok) throw new Error(data.error || 'Unknown error.');

                msgEl.style.background = '#d1fae5';
                msgEl.style.color      = '#065f46';
                msgEl.textContent      = '✅ Campaign sent to ' + data.sent + ' students!';
            } catch(e) {
                msgEl.style.background = '#fee2e2';
                msgEl.style.color      = '#991b1b';
                msgEl.textContent      = '❌ ' + e.message;
                sendBtn.disabled = false;
            }
        }

        // ── backToPutmeHome — hides all sub-screens, restores dashboard ──
        function backToPutmeHome() {
            // Stop any active exam timer to avoid ghost intervals
            if (_putme && _putme.timerInterval) {
                clearInterval(_putme.timerInterval);
                _putme.timerInterval = null;
            }
            // Hide all sub-screens
            document.getElementById('putme-result-wrap').classList.remove('active');
            document.getElementById('putme-exam-wrap').classList.remove('active');
            document.getElementById('study-hub-wrap').classList.remove('active');
            var ls = document.getElementById('leaderboard-screen');
            if (ls) ls.classList.remove('active');
            var ss = document.getElementById('sprint-screen');
            if (ss) ss.classList.remove('active');
            // Restore action grid explicitly (startPutmeExam hides it inline)
            var ag = document.getElementById('putme-action-grid');
            if (ag && window._authProfile && window._authProfile.selected_university) {
                ag.style.display = 'block';
            }
            showPostUtmeHome();
        }

