        // HEAD-TO-HEAD DUELS — Phase 4
        // ═══════════════════════════════════════════════════════════════════

        var _duel = {
            id:null, code:null, role:null, channel:null, pollInterval:null,
            questions:[], index:0, answers:{}, myScore:0, oppScore:0,
            myFinished:false, oppFinished:false, timerInterval:null, timeLeft:180,
            myName:'', oppName:'', oppOnline:false, started:false
        };

        function _duelGenCode() {
            var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
            var code = '';
            for (var i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
            return code;
        }

        function openDuelLobby() {
            if (!_postSupabase || !window._authUser) {
                alert('Please sign in to use Head-to-Head Duels.');
                return;
            }
            var old = document.getElementById('duel-overlay');
            if (old) old.remove();

            var overlay = document.createElement('div');
            overlay.id = 'duel-overlay';
            overlay.style.cssText = 'position:fixed;inset:0;background:var(--bg,#f4f7fb);z-index:99999;overflow-y:auto;';

            var header = document.createElement('div');
            header.style.cssText = 'background:linear-gradient(135deg,#c0392b,#8e24aa);color:#fff;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;';
            header.innerHTML = '<h2 style="margin:0;font-size:1.2rem;">\u2694\ufe0f Head-to-Head Duel</h2>';
            var backBtn = document.createElement('button');
            backBtn.textContent = '\u2190 Back';
            backBtn.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;padding:6px 14px;border-radius:20px;cursor:pointer;font-size:0.85rem;';
            backBtn.onclick = function() { closeDuel(); };
            header.appendChild(backBtn);

            var body = document.createElement('div');
            body.id = 'duel-body';
            body.style.cssText = 'max-width:520px;margin:0 auto;padding:30px 16px;';

            // Create card
            var createDiv = document.createElement('div');
            createDiv.style.cssText = 'background:#fff;border-radius:16px;padding:24px;margin-bottom:20px;box-shadow:0 2px 8px rgba(0,0,0,0.08);text-align:center;';
            createDiv.innerHTML = '<div style="font-size:2.5rem;margin-bottom:8px;">\u2694\ufe0f</div>' +
                '<h3 style="margin:0 0 8px;color:#1a2742;">Challenge a Friend</h3>' +
                '<p style="color:#888;font-size:0.88rem;margin:0 0 16px;">Create a duel room and share the code</p>';
            var createBtn = document.createElement('button');
            createBtn.textContent = 'Create a Duel';
            createBtn.style.cssText = 'background:linear-gradient(135deg,#c0392b,#8e24aa);color:#fff;border:none;padding:12px 32px;border-radius:25px;font-size:1rem;font-weight:700;cursor:pointer;width:100%;';
            createBtn.onclick = function() { createDuel(); };
            createDiv.appendChild(createBtn);

            // Divider
            var divider = document.createElement('div');
            divider.style.cssText = 'display:flex;align-items:center;gap:12px;margin-bottom:20px;color:#aaa;font-size:0.85rem;';
            divider.innerHTML = '<div style="flex:1;height:1px;background:#e0e0e0;"></div>or join one<div style="flex:1;height:1px;background:#e0e0e0;"></div>';

            // Join card
            var joinDiv = document.createElement('div');
            joinDiv.style.cssText = 'background:#fff;border-radius:16px;padding:24px;box-shadow:0 2px 8px rgba(0,0,0,0.08);';
            joinDiv.innerHTML = '<p style="color:#888;font-size:0.88rem;margin:0 0 12px;text-align:center;">Enter the code your friend shared</p>';
            var joinRow = document.createElement('div');
            joinRow.style.cssText = 'display:flex;gap:8px;';
            var codeInput = document.createElement('input');
            codeInput.id = 'duel-code-input';
            codeInput.type = 'text';
            codeInput.placeholder = 'Code (e.g. ABC123)';
            codeInput.maxLength = 6;
            codeInput.style.cssText = 'flex:1;padding:11px 14px;border:2px solid #e0e0e0;border-radius:10px;font-size:0.95rem;text-transform:uppercase;letter-spacing:0.1em;outline:none;';
            codeInput.oninput = function() { this.value = this.value.toUpperCase(); };
            var joinBtn = document.createElement('button');
            joinBtn.textContent = 'Join';
            joinBtn.style.cssText = 'background:#0056b3;color:#fff;border:none;padding:11px 22px;border-radius:10px;font-size:0.95rem;font-weight:700;cursor:pointer;';
            joinBtn.onclick = function() {
                var code = (document.getElementById('duel-code-input').value || '').trim().toUpperCase();
                if (code.length < 4) { alert('Please enter a valid duel code.'); return; }
                joinDuel(code);
            };
            joinRow.appendChild(codeInput);
            joinRow.appendChild(joinBtn);
            joinDiv.appendChild(joinRow);
            var errDiv = document.createElement('div');
            errDiv.id = 'duel-join-error';
            errDiv.style.cssText = 'color:#dc3545;font-size:0.82rem;margin-top:8px;';
            joinDiv.appendChild(errDiv);

            body.appendChild(createDiv);
            body.appendChild(divider);
            body.appendChild(joinDiv);
            overlay.appendChild(header);
            overlay.appendChild(body);
            document.body.appendChild(overlay);
        }

        async function createDuel() {
            var code   = _duelGenCode();
            var myName = (window._authProfile && window._authProfile.full_name) || 'Player 1';
            var myId   = window._authUser.id;
            var body   = document.getElementById('duel-body');
            body.innerHTML = '<p style="text-align:center;color:#888;padding:30px;">Creating duel room\u2026</p>';
            try {
                var ins = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ error:{ message:'Timeout' } }); }, 6000);
                    _postSupabase.from('duels')
                        .insert({ code:code, host_id:myId, host_name:myName, status:'waiting' })
                        .select().maybeSingle()
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(e){ clearTimeout(t); resolve({ error:e }); });
                });
                if (ins.error) {
                    body.innerHTML = '<p style="text-align:center;color:#dc3545;padding:30px;">Could not create duel: ' + (ins.error.message||'error') + '</p>';
                    return;
                }
                _duel.id=ins.data.id; _duel.code=code; _duel.role='host';
                _duel.myName=myName; _duel.oppName=''; _duel.myScore=0; _duel.oppScore=0;
                _duel.myFinished=false; _duel.oppFinished=false; _duel.oppOnline=false; _duel.started=false;
                _duelSubscribe(code);
                _duelShowWaiting();
            } catch(e) {
                body.innerHTML = '<p style="text-align:center;color:#dc3545;padding:30px;">Error creating duel.</p>';
            }
        }

        async function joinDuel(code) {
            var myName = (window._authProfile && window._authProfile.full_name) || 'Player 2';
            var myId   = window._authUser.id;
            var errEl  = document.getElementById('duel-join-error');
            if (errEl) errEl.textContent = 'Looking up duel\u2026';
            try {
                var found = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve({ data:null }); }, 6000);
                    _postSupabase.from('duels').select('*').eq('code',code).eq('status','waiting').maybeSingle()
                        .then(function(r){ clearTimeout(t); resolve(r); })
                        .catch(function(){ clearTimeout(t); resolve({ data:null }); });
                });
                if (!found.data) {
                    if (errEl) errEl.textContent = 'Duel not found or already started. Check the code.';
                    return;
                }
                var row = found.data;
                await new Promise(function(resolve) {
                    var t = setTimeout(resolve, 4000);
                    _postSupabase.from('duels').update({ guest_id:myId, guest_name:myName }).eq('id',row.id)
                        .then(function(){ clearTimeout(t); resolve(); }).catch(function(){ clearTimeout(t); resolve(); });
                });
                _duel.id=row.id; _duel.code=code; _duel.role='guest';
                _duel.myName=myName; _duel.oppName=row.host_name||'Host';
                _duel.myScore=0; _duel.oppScore=0;
                _duel.myFinished=false; _duel.oppFinished=false; _duel.oppOnline=true; _duel.started=false;
                _duelSubscribe(code);
                _duelShowWaiting();
            } catch(e) {
                if (errEl) errEl.textContent = 'Error joining duel. Please try again.';
            }
        }

        function _duelSubscribe(code) {
            if (_duel.channel) { try { _postSupabase.removeChannel(_duel.channel); } catch(e) {} }
            _duel.channel = _postSupabase.channel('duel_' + code);
            _duel.channel
                .on('broadcast', { event:'guest_joined' }, function(ev) {
                    _duel.oppName = ev.payload.name || 'Opponent';
                    _duel.oppOnline = true;
                    _duelUpdateWaiting();
                })
                .on('broadcast', { event:'duel_start' }, function(ev) {
                    if (_duel.role === 'guest') {
                        _duel.questions = ev.payload.questions || [];
                        clearInterval(_duel.pollInterval);
                        startDuelQuiz();
                    }
                })
                .on('broadcast', { event:'score_update' }, function(ev) {
                    _duel.oppScore = ev.payload.score || 0;
                    _duelUpdateScoreboard();
                })
                .on('broadcast', { event:'player_finished' }, function(ev) {
                    _duel.oppScore    = ev.payload.score || 0;
                    _duel.oppFinished = true;
                    _duelCheckBothDone();
                })
                .subscribe(function(status) {
                    if (status === 'SUBSCRIBED' && _duel.role === 'guest') {
                        _duel.channel.send({ type:'broadcast', event:'guest_joined', payload:{ name:_duel.myName } });
                    }
                });
            // Host polls DB every 3s as fallback for guest detection
            if (_duel.role === 'host') {
                clearInterval(_duel.pollInterval);
                _duel.pollInterval = setInterval(function() {
                    if (_duel.oppOnline || _duel.started) { clearInterval(_duel.pollInterval); return; }
                    _postSupabase.from('duels').select('guest_id,guest_name').eq('id',_duel.id).maybeSingle()
                        .then(function(r) {
                            if (r && r.data && r.data.guest_id && !_duel.oppOnline) {
                                _duel.oppName = r.data.guest_name || 'Opponent';
                                _duel.oppOnline = true;
                                _duelUpdateWaiting();
                            }
                        }).catch(function(){});
                }, 3000);
            }
        }

        function _duelShowWaiting() {
            var body = document.getElementById('duel-body');
            if (!body) return;
            body.style.cssText = 'max-width:460px;margin:0 auto;padding:24px 16px;';
            body.innerHTML = '';

            // Code display card
            var codeCard = document.createElement('div');
            codeCard.style.cssText = 'background:#fff;border-radius:16px;padding:24px;margin-bottom:14px;box-shadow:0 2px 8px rgba(0,0,0,0.08);text-align:center;';
            if (_duel.role === 'host') {
                codeCard.innerHTML = '<div style="font-size:0.78rem;color:#888;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:6px;">Share this code with your friend</div>' +
                    '<div style="font-size:3rem;font-weight:900;color:#c0392b;letter-spacing:0.25em;font-family:monospace;">' + _duel.code + '</div>' +
                    '<div style="font-size:0.75rem;color:#aaa;margin-top:4px;">10 questions \u00b7 3 minutes</div>';
                var copyBtn = document.createElement('button');
                copyBtn.textContent = '📋 Copy Code';
                copyBtn.style.cssText = 'margin-top:10px;background:#f3e8ff;color:#7c3aed;border:none;padding:6px 16px;border-radius:20px;font-size:0.8rem;font-weight:700;cursor:pointer;';
                copyBtn.onclick = function() {
                    navigator.clipboard.writeText(_duel.code).then(function(){
                        copyBtn.textContent = '\u2713 Copied!';
                        setTimeout(function(){ copyBtn.textContent = '📋 Copy Code'; }, 1500);
                    }).catch(function(){});
                };
                codeCard.appendChild(copyBtn);
            } else {
                codeCard.innerHTML = '<div style="font-size:0.78rem;color:#888;margin-bottom:6px;">Joined duel</div>' +
                    '<div style="font-size:3rem;font-weight:900;color:#c0392b;letter-spacing:0.25em;font-family:monospace;">' + _duel.code + '</div>' +
                    '<div style="font-size:0.78rem;color:#aaa;margin-top:4px;">Waiting for host to start\u2026</div>';
            }

            // Players card
            var playersCard = document.createElement('div');
            playersCard.id = 'duel-players-card';
            playersCard.style.cssText = 'background:#fff;border-radius:16px;padding:18px;margin-bottom:14px;box-shadow:0 2px 8px rgba(0,0,0,0.08);';

            // Start / wait area
            var actionWrap = document.createElement('div');
            actionWrap.id = 'duel-action-wrap';
            if (_duel.role === 'host') {
                var startBtn = document.createElement('button');
                startBtn.id = 'duel-start-btn';
                startBtn.textContent = 'Start Duel';
                startBtn.disabled = true;
                startBtn.style.cssText = 'width:100%;padding:14px;background:linear-gradient(135deg,#c0392b,#8e24aa);color:#fff;border:none;border-radius:14px;font-size:1rem;font-weight:700;cursor:pointer;opacity:0.45;';
                startBtn.onclick = function() { if (!startBtn.disabled) startDuel(); };
                var hint = document.createElement('p');
                hint.id = 'duel-start-hint';
                hint.style.cssText = 'text-align:center;color:#aaa;font-size:0.78rem;margin-top:8px;';
                hint.textContent = 'Waiting for opponent to join\u2026';
                actionWrap.appendChild(startBtn);
                actionWrap.appendChild(hint);
            } else {
                var waitP = document.createElement('p');
                waitP.style.cssText = 'text-align:center;color:#888;font-size:0.88rem;padding:8px 0;';
                waitP.innerHTML = '\u23F3 Waiting for host to start\u2026';
                actionWrap.appendChild(waitP);
            }

            body.appendChild(codeCard);
            body.appendChild(playersCard);
            body.appendChild(actionWrap);
            _duelUpdateWaiting();
        }

        function _duelUpdateWaiting() {
            var card = document.getElementById('duel-players-card');
            if (!card) return;
            var oppLabel  = _duel.oppOnline ? (_duel.oppName || 'Opponent') : '\u2014';
            var oppStatus = _duel.oppOnline ? '\u2705 Online' : '\u23F3 Waiting\u2026';
            card.innerHTML = '<div style="font-weight:700;color:#1a2742;font-size:0.8rem;margin-bottom:10px;text-transform:uppercase;letter-spacing:0.05em;">Players</div>' +
                '<div style="display:flex;flex-direction:column;gap:8px;">' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:#f0f7ff;border-radius:10px;">' +
                    '<div style="font-weight:700;color:#1a2742;">' + _duel.myName + ' <span style="font-size:0.72rem;color:#0056b3;">(You)</span></div>' +
                    '<div style="font-size:0.8rem;color:#28a745;font-weight:600;">\u2705 Online</div>' +
                '</div>' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:#fafafa;border-radius:10px;">' +
                    '<div style="font-weight:700;color:#1a2742;">' + oppLabel + '</div>' +
                    '<div style="font-size:0.8rem;color:' + (_duel.oppOnline ? '#28a745' : '#888') + ';font-weight:600;">' + oppStatus + '</div>' +
                '</div></div>';
            if (_duel.role === 'host' && _duel.oppOnline) {
                var sb = document.getElementById('duel-start-btn');
                var sh = document.getElementById('duel-start-hint');
                if (sb) { sb.disabled = false; sb.style.opacity = '1'; }
                if (sh) { sh.textContent = (_duel.oppName || 'Opponent') + ' has joined! Ready?'; sh.style.color = '#28a745'; }
            }
        }

        async function startDuel() {
            var btn = document.getElementById('duel-start-btn');
            if (btn) { btn.disabled = true; btn.textContent = 'Loading questions\u2026'; btn.style.opacity = '0.6'; }
            var subjects = (_putme.subjects && _putme.subjects.length > 0) ? _putme.subjects : ['Use of English'];
            var uni = (window._authProfile && window._authProfile.selected_university) || (_putme.university || '');
            try {
                var allQs = await new Promise(function(resolve) {
                    var t = setTimeout(function(){ resolve([]); }, 6000);
                    var q = _postSupabase.from('question_bank')
                        .select('id,subject,question,option_a,option_b,option_c,option_d,correct_answer,explanation')
                        .in('subject', subjects);
                    if (uni) q = q.or('university.eq.' + uni + ',university.is.null,university.eq.ALL');
                    else     q = q.or('university.is.null,university.eq.ALL');
                    q.limit(100)
                     .then(function(r){
                         clearTimeout(t);
                         resolve((r.data||[]).map(function(q) {
                             return {
                                 id: q.id, subject: q.subject, question: q.question,
                                 options: [q.option_a, q.option_b, q.option_c, q.option_d],
                                 answer: ['A','B','C','D'].indexOf((q.correct_answer||'').toUpperCase()),
                                 explanation: q.explanation
                             };
                         }));
                     })
                     .catch(function(){ clearTimeout(t); resolve([]); });
                });
                if (allQs.length < 5) {
                    if (btn) { btn.disabled=false; btn.textContent='Start Duel'; btn.style.opacity='1'; }
                    alert('Not enough questions in the bank. Ask your admin to add more.');
                    return;
                }
                allQs.sort(function(){ return Math.random() - 0.5; });
                _duel.questions = allQs.slice(0, 10);
                _duel.started   = true;
                clearInterval(_duel.pollInterval);
                _duel.channel.send({ type:'broadcast', event:'duel_start', payload:{ questions:_duel.questions } });
                _postSupabase.from('duels').update({ status:'active' }).eq('id',_duel.id)
                    .then(function(){}).catch(function(){});
                startDuelQuiz();
            } catch(e) {
                if (btn) { btn.disabled=false; btn.textContent='Start Duel'; btn.style.opacity='1'; }
                alert('Error starting duel. Please try again.');
            }
        }

        function startDuelQuiz() {
            _duel.index=0; _duel.answers={}; _duel.myScore=0;
            _duel.myFinished=false; _duel.timeLeft=180;
            var body = document.getElementById('duel-body');
            if (!body) return;
            body.style.cssText = 'max-width:600px;margin:0 auto;padding:14px;';
            body.innerHTML = '';

            var sb = document.createElement('div');
            sb.id = 'duel-scoreboard';
            sb.style.cssText = 'display:grid;grid-template-columns:1fr auto 1fr;align-items:center;background:#fff;border-radius:14px;padding:12px 18px;margin-bottom:10px;box-shadow:0 2px 8px rgba(0,0,0,0.07);';

            var timerRow = document.createElement('div');
            timerRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;';
            var timerEl = document.createElement('div');
            timerEl.id = 'duel-timer';
            timerEl.style.cssText = 'background:linear-gradient(135deg,#c0392b,#8e24aa);color:#fff;font-weight:900;font-size:1.05rem;padding:6px 16px;border-radius:20px;';
            timerEl.textContent = '3:00';
            var progEl = document.createElement('div');
            progEl.id = 'duel-progress';
            progEl.style.cssText = 'font-size:0.78rem;color:#888;';
            progEl.textContent = 'Q 1 / ' + _duel.questions.length;
            timerRow.appendChild(timerEl);
            timerRow.appendChild(progEl);

            var qCard = document.createElement('div');
            qCard.id = 'duel-question-card';
            qCard.style.cssText = 'background:#fff;border-radius:16px;padding:20px;box-shadow:0 2px 8px rgba(0,0,0,0.07);';

            body.appendChild(sb);
            body.appendChild(timerRow);
            body.appendChild(qCard);
            _duelUpdateScoreboard();
            _duelRenderQuestion();
            _duelTimerStart();
        }

        function _duelUpdateScoreboard() {
            var sb = document.getElementById('duel-scoreboard');
            if (!sb) return;
            sb.innerHTML =
                '<div style="text-align:center;">' +
                    '<div style="font-size:0.68rem;color:#888;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:1px;">You</div>' +
                    '<div style="font-size:2.2rem;font-weight:900;color:#0056b3;">' + _duel.myScore + '</div>' +
                    '<div style="font-size:0.72rem;color:#555;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px;">' + _duel.myName + '</div>' +
                '</div>' +
                '<div style="text-align:center;font-size:1.3rem;padding:0 6px;">\u2694\ufe0f</div>' +
                '<div style="text-align:center;">' +
                    '<div style="font-size:0.68rem;color:#888;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:1px;">Opp</div>' +
                    '<div style="font-size:2.2rem;font-weight:900;color:#c0392b;">' + _duel.oppScore + '</div>' +
                    '<div style="font-size:0.72rem;color:#555;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px;">' + (_duel.oppName || 'Opponent') + '</div>' +
                '</div>';
        }

        function _duelRenderQuestion() {
            var card = document.getElementById('duel-question-card');
            var prog = document.getElementById('duel-progress');
            if (!card || !_duel.questions[_duel.index]) return;
            var q = _duel.questions[_duel.index];
            if (prog) prog.textContent = 'Q ' + (_duel.index + 1) + ' / ' + _duel.questions.length;

            var subj = document.createElement('div');
            subj.style.cssText = 'font-size:0.72rem;color:#0056b3;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;';
            subj.textContent = q.subject || '';

            var qText = document.createElement('div');
            qText.style.cssText = 'font-size:0.93rem;color:#1a2742;font-weight:600;line-height:1.5;margin-bottom:14px;';
            qText.textContent = q.question;

            var optsWrap = document.createElement('div');
            optsWrap.style.cssText = 'display:flex;flex-direction:column;gap:7px;';
            var opts = q.options || [];
            opts.forEach(function(opt, i) {
                var btn = document.createElement('button');
                btn.style.cssText = 'width:100%;text-align:left;padding:10px 13px;border:2px solid #e8eaf0;border-radius:10px;background:#fafafa;color:#1a2742;font-size:0.87rem;cursor:pointer;';
                var label = document.createElement('span');
                label.style.cssText = 'font-weight:700;margin-right:8px;';
                label.textContent = String.fromCharCode(65 + i) + '.';
                btn.appendChild(label);
                btn.appendChild(document.createTextNode(opt));
                (function(idx) { btn.onclick = function() { _duelAnswer(idx); }; })(i);
                optsWrap.appendChild(btn);
            });

            card.innerHTML = '';
            card.appendChild(subj);
            card.appendChild(qText);
            card.appendChild(optsWrap);
        }

        function _duelAnswer(idx) {
            var q = _duel.questions[_duel.index];
            if (!q || _duel.answers[_duel.index] !== undefined) return;
            _duel.answers[_duel.index] = idx;
            var correct = (idx === q.answer);
            if (correct) {
                _duel.myScore++;
                _duel.channel.send({ type:'broadcast', event:'score_update', payload:{ score:_duel.myScore } });
                _duelUpdateScoreboard();
            }
            // Highlight answer
            var card = document.getElementById('duel-question-card');
            if (card) {
                var btns = card.querySelectorAll('button');
                btns.forEach(function(b, i) {
                    b.style.pointerEvents = 'none';
                    if (i === q.answer)          { b.style.borderColor='#28a745'; b.style.background='#d4edda'; b.style.color='#155724'; }
                    else if (i === idx && !correct) { b.style.borderColor='#dc3545'; b.style.background='#f8d7da'; b.style.color='#721c24'; }
                });
                if (q.explanation) {
                    var ex = document.createElement('div');
                    ex.style.cssText = 'margin-top:10px;padding:9px 12px;background:#fff8e1;border-radius:8px;font-size:0.78rem;color:#555;border-left:3px solid #ffc107;';
                    ex.textContent = q.explanation;
                    card.appendChild(ex);
                }
            }
            setTimeout(function() {
                _duel.index++;
                if (_duel.index >= _duel.questions.length) { finishDuel(); }
                else { _duelRenderQuestion(); }
            }, correct ? 600 : 1000);
        }

        function _duelTimerStart() {
            clearInterval(_duel.timerInterval);
            _duel.timerInterval = setInterval(function() {
                _duel.timeLeft--;
                var m = Math.floor(_duel.timeLeft / 60);
                var s = _duel.timeLeft % 60;
                var el = document.getElementById('duel-timer');
                if (el) {
                    el.textContent = m + ':' + (s < 10 ? '0' : '') + s;
                    if (_duel.timeLeft <= 30) el.style.background = 'linear-gradient(135deg,#dc3545,#c0392b)';
                }
                if (_duel.timeLeft <= 0) { clearInterval(_duel.timerInterval); finishDuel(); }
            }, 1000);
        }

        function finishDuel() {
            if (_duel.myFinished) return;
            _duel.myFinished = true;
            clearInterval(_duel.timerInterval);
            _duel.channel.send({ type:'broadcast', event:'player_finished', payload:{ score:_duel.myScore } });
            var upd = _duel.role === 'host'
                ? { host_score:_duel.myScore, host_finished:true }
                : { guest_score:_duel.myScore, guest_finished:true };
            _postSupabase.from('duels').update(upd).eq('id',_duel.id)
                .then(function(){}).catch(function(){});
            if (!_duel.oppFinished) {
                var card = document.getElementById('duel-question-card');
                if (card) {
                    card.innerHTML = '<div style="text-align:center;padding:28px;color:#888;">' +
                        '<div style="font-size:2.5rem;margin-bottom:10px;">\u23F3</div>' +
                        '<div style="font-weight:700;color:#1a2742;font-size:1.05rem;">You finished!</div>' +
                        '<div style="font-size:0.85rem;margin-top:6px;">Score: <strong>' + _duel.myScore + '/' + _duel.questions.length + '</strong></div>' +
                        '<div style="font-size:0.8rem;color:#aaa;margin-top:8px;">Waiting for ' + (_duel.oppName||'opponent') + ' to finish\u2026</div>' +
                        '</div>';
                }
                window._duelWaitTimeout = setTimeout(function(){ showDuelResult(); }, 45000);
            } else {
                _duelCheckBothDone();
            }
        }

        function _duelCheckBothDone() {
            if (_duel.myFinished && _duel.oppFinished) {
                clearTimeout(window._duelWaitTimeout);
                showDuelResult();
            }
        }

        function showDuelResult() {
            clearInterval(_duel.timerInterval);
            clearInterval(_duel.pollInterval);
            var total   = _duel.questions.length || 10;
            var myPct   = Math.round((_duel.myScore / total) * 100);
            var oppPct  = Math.round((_duel.oppScore / total) * 100);
            var outcome = _duel.myScore > _duel.oppScore ? 'win' : _duel.myScore < _duel.oppScore ? 'lose' : 'draw';
            var winner  = outcome === 'win' ? _duel.myName : outcome === 'lose' ? (_duel.oppName||'Opponent') : 'Draw';
            _postSupabase.from('duels').update({ status:'finished', winner:winner }).eq('id',_duel.id)
                .then(function(){}).catch(function(){});

            var body = document.getElementById('duel-body');
            if (!body) return;
            body.style.cssText = 'max-width:480px;margin:0 auto;padding:20px 16px;';
            body.innerHTML = '';

            var bannerBg   = outcome==='win' ? 'linear-gradient(135deg,#28a745,#20c997)' : outcome==='lose' ? 'linear-gradient(135deg,#dc3545,#c0392b)' : 'linear-gradient(135deg,#6c757d,#495057)';
            var bannerIcon = outcome==='win' ? '🏆' : outcome==='lose' ? '💪' : '🤝';
            var bannerText = outcome==='win' ? 'You Win!' : outcome==='lose' ? 'Keep Going!' : 'Tied!';

            var banner = document.createElement('div');
            banner.style.cssText = 'background:' + bannerBg + ';border-radius:20px;padding:28px;text-align:center;color:#fff;margin-bottom:18px;';
            banner.innerHTML = '<div style="font-size:3rem;margin-bottom:8px;">' + bannerIcon + '</div>' +
                '<div style="font-size:1.6rem;font-weight:900;">' + bannerText + '</div>';

            var scoresCard = document.createElement('div');
            scoresCard.style.cssText = 'background:#fff;border-radius:16px;padding:18px;margin-bottom:18px;box-shadow:0 2px 8px rgba(0,0,0,0.08);';

            var p1 = { name:_duel.myName+' (You)', score:_duel.myScore, pct:myPct,  top:outcome==='win',  col:'#0056b3' };
            var p2 = { name:_duel.oppName||'Opponent', score:_duel.oppScore, pct:oppPct, top:outcome==='lose', col:'#c0392b' };
            var sorted = (p1.score >= p2.score) ? [p1,p2] : [p2,p1];

            var sHTML = '<div style="font-weight:700;color:#1a2742;margin-bottom:12px;font-size:0.82rem;text-transform:uppercase;letter-spacing:0.05em;">Final Scores</div>';
            sorted.forEach(function(p, i) {
                var medal = i===0 ? (outcome==='draw'?'🤝':'🥇') : '🥈';
                sHTML += '<div style="display:flex;align-items:center;gap:12px;padding:11px 14px;border-radius:10px;background:' + (p.top?'#f0fff4':'#fafafa') + ';margin-bottom:8px;border:2px solid ' + (p.top?'#28a745':'#f0f0f0') + ';">' +
                    '<span style="font-size:1.8rem;">' + medal + '</span>' +
                    '<div style="flex:1;font-weight:700;color:#1a2742;">' + p.name + '</div>' +
                    '<div style="text-align:right;"><div style="font-size:1.2rem;font-weight:900;color:' + p.col + ';">' + p.score + '/' + total + '</div><div style="font-size:0.72rem;color:#888;">' + p.pct + '%</div></div>' +
                    '</div>';
            });
            scoresCard.innerHTML = sHTML;

            var btnsRow = document.createElement('div');
            btnsRow.style.cssText = 'display:flex;gap:10px;';

            var rematchBtn = document.createElement('button');
            rematchBtn.textContent = '🔄 Rematch';
            rematchBtn.style.cssText = 'flex:1;padding:13px;background:linear-gradient(135deg,#c0392b,#8e24aa);color:#fff;border:none;border-radius:12px;font-size:0.95rem;font-weight:700;cursor:pointer;';
            rematchBtn.onclick = function() { var o=document.getElementById('duel-overlay'); if(o)o.remove(); openDuelLobby(); };

            var closeBtn = document.createElement('button');
            closeBtn.textContent = 'Close';
            closeBtn.style.cssText = 'flex:1;padding:13px;background:#f0f0f0;color:#333;border:none;border-radius:12px;font-size:0.95rem;font-weight:700;cursor:pointer;';
            closeBtn.onclick = function() { closeDuel(); };

            btnsRow.appendChild(rematchBtn);
            btnsRow.appendChild(closeBtn);
            body.appendChild(banner);
            body.appendChild(scoresCard);
            body.appendChild(btnsRow);
        }

        function closeDuel() {
            clearInterval(_duel.timerInterval);
            clearInterval(_duel.pollInterval);
            clearTimeout(window._duelWaitTimeout);
            if (_duel.channel) { try { _postSupabase.removeChannel(_duel.channel); } catch(e){} _duel.channel=null; }
            _duel = { id:null,code:null,role:null,channel:null,pollInterval:null,
                questions:[],index:0,answers:{},myScore:0,oppScore:0,
                myFinished:false,oppFinished:false,timerInterval:null,timeLeft:180,
                myName:'',oppName:'',oppOnline:false,started:false };
            var el = document.getElementById('duel-overlay');
            if (el) el.remove();
        }

        // ═══════════════════════════════════════════════════════════════
        // THEME SWITCHER — saas | dark-glass | light-glass
        // Reads/writes localStorage key 'app_theme'.
        // Only touches <html data-theme> — zero impact on other logic.
        // ═══════════════════════════════════════════════════════════════
        (function () {
            function setTheme(t) {
                document.documentElement.setAttribute('data-theme', t);
                try { localStorage.setItem('app_theme', t); } catch(e) {}
                // Update active-state on option buttons
                document.querySelectorAll('.theme-opt-btn').forEach(function(btn){
                    btn.classList.toggle('active', btn.getAttribute('data-t') === t);
                });
            }

            function _toggleThemeMenu() {
                var opts = document.getElementById('theme-options');
                if (!opts) return;
                var open = opts.classList.toggle('open');
                // Close on outside click
                if (open) {
                    setTimeout(function(){
                        document.addEventListener('click', function _close(e){
                            if (!e.target.closest('#theme-switcher')) {
                                var o = document.getElementById('theme-options');
                                if (o) o.classList.remove('open');
                                document.removeEventListener('click', _close);
                            }
                        });
                    }, 10);
                }
            }

            // Expose globally so onclick="" attributes work
            window.setTheme        = setTheme;
            window._toggleThemeMenu = _toggleThemeMenu;

            // Apply saved theme immediately (anti-FOUC already ran in <head>,
            // but this ensures button active-states are painted correctly)
            var saved = 'dark-glass';
            try { saved = localStorage.getItem('app_theme') || 'dark-glass'; } catch(e) {}
            setTheme(saved);
        }());

// ── PWA Install Banner ────────────────────────────────────────
(function() {
    // Don't show if already running as installed PWA
    if (window.matchMedia('(display-mode: standalone)').matches) return;
    if (window.navigator.standalone === true) return;
    // Don't show if user dismissed this session
    try { if (sessionStorage.getItem('pwa_dismissed')) return; } catch(e) {}

    var deferredPrompt = null;
    var isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;

    function showBanner() {
        // Don't show if already dismissed this session
        try { if (sessionStorage.getItem('pwa_dismissed')) return; } catch(e) {}
        // Don't show if the portal selector or auth overlay is currently visible
        var ps = document.getElementById('portal-selector');
        if (ps && ps.classList.contains('visible')) return;
        var auth = document.getElementById('auth-overlay');
        if (auth && !auth.classList.contains('hidden')) return;
        var banner = document.getElementById('pwa-install-banner');
        if (banner) banner.style.display = 'flex';
    }
    function hideBanner() {
        var banner = document.getElementById('pwa-install-banner');
        if (banner) banner.style.display = 'none';
        try { sessionStorage.setItem('pwa_dismissed', '1'); } catch(e) {}
    }

    // Capture Android/Chrome install prompt
    window.addEventListener('beforeinstallprompt', function(e) {
        e.preventDefault();
        deferredPrompt = e;
    });

    // Install button click
    window.addEventListener('load', function() {
        var btnInst = document.getElementById('pwa-install-btn');
        var btnDis  = document.getElementById('pwa-dismiss-btn');
        var subText = document.getElementById('pwa-banner-sub');

        // iOS — swap text, hide install button
        if (isIOS && subText && btnInst) {
            subText.textContent = 'Tap 📤 Share → "Add to Home Screen"';
            btnInst.style.display = 'none';
        }

        // Install button (Android/Chrome)
        if (btnInst) {
            btnInst.addEventListener('click', function() {
                if (deferredPrompt) {
                    deferredPrompt.prompt();
                    deferredPrompt.userChoice.then(function(r) {
                        if (r.outcome === 'accepted') hideBanner();
                        deferredPrompt = null;
                    });
                }
            });
        }

        if (btnDis) btnDis.addEventListener('click', hideBanner);
        window.addEventListener('appinstalled', function() {
            hideBanner();
            _pwaShowToast('✅ App installed! Open it from your home screen.');
        });

        // If already running as installed PWA, show a welcome indicator once
        if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
            try {
                if (!sessionStorage.getItem('pwa_welcomed')) {
                    sessionStorage.setItem('pwa_welcomed', '1');
                    setTimeout(function() {
                        _pwaShowToast('📲 Running as installed app');
                    }, 1500);
                }
            } catch(e) {}
        }

        // Show banner — retry every 8 s until it successfully displays (up to 10 attempts)
        var _bannerTries = 0;
        function _tryShowBanner() {
            _bannerTries++;
            try { if (sessionStorage.getItem('pwa_dismissed')) return; } catch(e) {}
            var _ps   = document.getElementById('portal-selector');
            var _auth = document.getElementById('auth-overlay');
            var _onPortal = _ps   && _ps.classList.contains('visible');
            var _onAuth   = _auth && !_auth.classList.contains('hidden');
            if (!_onPortal && !_onAuth) {
                showBanner();   // conditions met — show it
            } else if (_bannerTries < 10) {
                setTimeout(_tryShowBanner, 8000);  // still gating screen visible, retry
            }
        }
        setTimeout(_tryShowBanner, 10000);  // first attempt at 10 s
    });
}());
// PWA toast helper (used by install banner)
function _pwaShowToast(msg) {
    var t = document.getElementById('pwa-toast');
    if (!t) {
        t = document.createElement('div');
        t.id = 'pwa-toast';
        document.body.appendChild(t);
    }
    t.textContent = msg;
    t.className = 'pwa-toast-show';
    clearTimeout(t._timer);
    t._timer = setTimeout(function() { t.className = ''; }, 3500);
}

// ─────────────────────────────────────────────────────────────

// ── PWA Update Detection ──────────────────────────────────────
(function() {
    if (!('serviceWorker' in navigator)) return;

    var _waitingWorker = null;

    function showUpdateToast() {
        var t = document.getElementById('pwa-update-toast');
        if (!t) {
            t = document.createElement('div');
            t.id = 'pwa-update-toast';
            t.innerHTML = '🔄 Update available — <strong>tap to refresh</strong>';
            t.style.cssText = [
                'position:fixed', 'bottom:90px', 'left:50%',
                'transform:translateX(-50%)', 'background:#d4a017',
                'color:#1a2742', 'border-radius:24px', 'padding:12px 22px',
                'font-size:0.85rem', 'font-weight:700', 'white-space:nowrap',
                'z-index:9999999', 'cursor:pointer', 'box-shadow:0 4px 16px rgba(0,0,0,0.3)',
                'animation:pwa-slide-up 0.35s ease'
            ].join(';');
            t.addEventListener('click', function() {
                if (_waitingWorker) {
                    _waitingWorker.postMessage('SKIP_WAITING');
                }
                t.innerHTML = '⏳ Refreshing…';
                t.style.cursor = 'default';
            });
            document.body.appendChild(t);
        }
    }

    // Reload the page once the new SW takes control
    navigator.serviceWorker.addEventListener('controllerchange', function() {
        window.location.reload();
    });

    navigator.serviceWorker.ready.then(function(reg) {
        // New SW found while page is open
        reg.addEventListener('updatefound', function() {
            var newWorker = reg.installing;
            newWorker.addEventListener('statechange', function() {
                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                    _waitingWorker = newWorker;
                    showUpdateToast();
                }
            });
        });

        // SW was already waiting when the page loaded (e.g. tab was left open)
        if (reg.waiting && navigator.serviceWorker.controller) {
            _waitingWorker = reg.waiting;
            showUpdateToast();
        }
    });
}());
